export function node(tag, className = '', text = '') {
  const item = document.createElement(tag);
  if (className) item.className = className;
  if (text !== undefined && text !== null) item.textContent = String(text);
  return item;
}

export function button(label, className, onClick, type = 'button') {
  const item = node('button', className, label);
  item.type = type;
  if (onClick) item.addEventListener('click', onClick);
  return item;
}

export function field(labelText, value, options = {}) {
  const wrap = node('label', 'field');
  wrap.append(node('span', 'field-label', labelText));

  let input;
  if (options.type === 'textarea') {
    input = node('textarea', 'control');
    input.rows = options.rows || 3;
  } else if (options.type === 'select') {
    input = node('select', 'control');
    for (const choice of options.options || []) {
      const option = node('option', '', choice.label);
      option.value = choice.value;
      input.append(option);
    }
  } else {
    input = node('input', 'control');
    input.type = options.type || 'text';
  }

  input.value = value ?? '';
  if (options.placeholder) input.placeholder = options.placeholder;
  if (options.min !== undefined) input.min = options.min;
  if (options.max !== undefined) input.max = options.max;
  if (options.step !== undefined) input.step = options.step;
  if (options.required) input.required = true;
  if (options.path) input.dataset.path = options.path;
  wrap.append(input);
  return wrap;
}

export function checkbox(labelText, checked, path = '') {
  const wrap = node('label', 'check-field');
  const input = node('input');
  input.type = 'checkbox';
  input.checked = Boolean(checked);
  if (path) input.dataset.path = path;
  wrap.append(input, node('span', 'checkmark'), node('span', '', labelText));
  return wrap;
}

export function card(title, description = '') {
  const element = node('section', 'panel-card');
  const heading = node('div', 'panel-heading');
  heading.append(node('h2', '', title));
  if (description) heading.append(node('p', 'muted', description));
  element.append(heading);
  return element;
}

export function statCard(label, value, note, indicator = 'ai-dot') {
  const item = node('article', 'stat-card');
  const top = node('div', 'stat-top');
  top.append(node('span', 'stat-label', label), node('span', `stat-indicator ${indicator}`));
  item.append(top, node('strong', 'stat-value', value), node('span', 'stat-note', note));
  return item;
}

export function statusLine(label, okay, note) {
  const row = node('div', 'status-row');
  const dot = node('span', `status-dot ${okay ? 'is-ok' : 'is-off'}`);
  const text = node('div', 'status-copy');
  text.append(node('strong', '', label), node('span', '', note));
  row.append(dot, text, node('span', `status-pill ${okay ? 'is-ok' : 'is-off'}`, okay ? 'READY' : 'SETUP'));
  return row;
}

export function emptyState(message) {
  return node('div', 'empty-state', message);
}

