import { notify, request } from './api.js';
import { node } from './dom.js';
import { createShell } from './shell.js';
import { loadData, onRender, render as requestRender, state } from './store.js';
import { renderOverview } from './views/overview.js';
import { renderContent } from './views/content.js';
import { renderAudit } from './views/audit.js';
import { renderRoles } from './views/roles.js';
import {
  renderBrand, renderCopy, renderEnvironment, renderFaq, renderLinks, renderMedia, renderRules, renderTheme
} from './views/settings.js';
import { createPreloader, imageReady, stylesReady } from '../shared/preloader.js';

const VIEWS = {
  overview: renderOverview,
  content: renderContent,
  brand: renderBrand,
  theme: renderTheme,
  copy: renderCopy,
  links: renderLinks,
  media: renderMedia,
  rules: renderRules,
  faq: renderFaq,
  roles: renderRoles,
  environment: renderEnvironment,
  audit: renderAudit
};

const REDIRECT_SECONDS = 10;

function applyAdminTheme() {
  // Executive Crimson Red Theme for Admin Command Center
  const color = state.data?.settings?.appearance?.accentColor || '#e63946';
  // If the stored color is the pale rose #c97f83, promote admin to vibrant executive crimson red #e63946
  const adminColor = (color.toLowerCase() === '#c97f83') ? '#e63946' : color;
  const channels = [1, 3, 5].map((offset) => Number.parseInt(adminColor.slice(offset, offset + 2), 16));
  document.documentElement.style.setProperty('--admin-accent', adminColor);
  document.documentElement.style.setProperty('--admin-accent-rgb', channels.join(', '));
}

function render() {
  const root = document.getElementById('app');
  if (!root) return;
  applyAdminTheme();
  const view = createShell(root);

  if (!state.data) {
    view.append(node('div', 'empty-state', 'Loading admin data…'));
    return;
  }

  const renderer = VIEWS[state.tab] || renderOverview;
  renderer(view);
}

function startRedirectCountdown(panel) {
  const counter = panel.querySelector('[data-redirect-countdown]');
  const bar = panel.querySelector('.session-redirect-bar');
  if (bar) bar.style.animationDuration = `${REDIRECT_SECONDS}s`;

  let remaining = REDIRECT_SECONDS;
  if (counter) counter.textContent = String(remaining);

  const timer = window.setInterval(() => {
    remaining -= 1;
    if (counter) counter.textContent = String(Math.max(0, remaining));
    if (remaining <= 0) window.clearInterval(timer);
  }, 1000);

  window.setTimeout(() => window.location.replace('/'), REDIRECT_SECONDS * 1000);
}

function renderSessionError(root, message) {
  root.replaceChildren();
  const panel = node('section', 'access-card session-denied');

  const mark = node('div', 'access-mark');
  const logo = node('img', 'access-logo');
  logo.src = state.data?.brand?.logo || '/assets/brand/logo.gif';
  logo.alt = state.data?.brand?.name || 'Server logo';
  mark.append(logo);

  const brand = node('p', 'access-brand', state.data?.brand?.name || 'WAKTU SENJA');
  const title = node('h1', '', 'You are not allowed');
  const copy = node('p', 'access-message', message);

  const countdown = node('div', 'session-redirect');
  const track = node('div', 'session-redirect-track');
  const bar = node('span', 'session-redirect-bar');
  track.append(bar);

  const text = node('p', 'session-redirect-text');
  const counter = node('strong', '', String(REDIRECT_SECONDS));
  counter.dataset.redirectCountdown = '';
  text.append('Returning to the website in ', counter, 's');
  countdown.append(track, text);

  panel.append(mark, brand, title, copy, countdown);
  root.append(panel);
  startRedirectCountdown(panel);
}

function startEvents() {
  const events = new EventSource('/api/events');
  events.onmessage = async () => {
    try {
      await loadData(false);
      if (state.tab === 'overview' || state.tab === 'roles') requestRender();
    } catch {
      // A temporary refresh failure does not close the admin panel.
    }
  };
}

async function boot() {
  const root = document.getElementById('app');
  if (!root) return;
  root.className = 'admin-app';

  const preloader = createPreloader({
    tasks: ['styles', 'fonts', 'logo', 'session', 'data', 'render'],
    labels: {
      styles: 'Loading styles',
      fonts: 'Preparing type',
      logo: 'Loading brand',
      session: 'Checking Discord access',
      data: 'Loading control center',
      render: 'Building the panel',
      ready: 'Access granted'
    }
  });

  preloader.track('styles', stylesReady());
  preloader.track('fonts', document.fonts?.ready || Promise.resolve());
  preloader.track('logo', imageReady(document.querySelector('.preloader-logo')));

  onRender(render);

  let session;
  try {
    session = await request('/api/admin/me');
  } catch (error) {
    preloader.mark('session');
    await preloader.complete();
    renderSessionError(root, error.message);
    return;
  }

  preloader.mark('session');
  state.user = session.user;

  try {
    await preloader.track('data', loadData(false));
  } catch (error) {
    await preloader.complete();
    renderSessionError(root, error.message);
    return;
  }

  render();
  preloader.mark('render');
  await preloader.complete();
  startEvents();
}

document.addEventListener('DOMContentLoaded', () => {
  boot().catch((error) => {
    console.error('[admin] Bootstrap failed:', error);
    notify('The admin panel could not start. Reload the page.', true);
  });
});

