import { button, node } from './dom.js';
import { NAV_GROUPS, NAV_ITEMS, goTo, render, state } from './store.js';
import { notify, request } from './api.js';

function brandBlock() {
  const brand = node('a', 'admin-brand');
  brand.href = '/';

  const mark = node('span', 'brand-symbol');
  const logo = state.data?.brand?.logo;
  if (logo) {
    const image = node('img', 'brand-logo');
    image.src = logo;
    image.alt = state.data?.brand?.name || 'Server logo';
    mark.append(image);
  } else {
    mark.textContent = (state.data?.brand?.name || 'WS').slice(0, 2).toUpperCase();
  }

  const copy = node('div', 'brand-copy-wrap');
  const title = node('div', 'brand-main-title');
  const span = node('span', 'brand-accent-text', 'SENJA');
  title.append('WAKTU ', span);

  const sub = node('div', 'brand-sub-title', 'FIVEM ROLEPLAY COMMUNITY');
  copy.append(title, sub);

  brand.append(mark, copy);
  return brand;
}

function navigation() {
  const nav = node('nav', 'side-navigation');
  for (const group of NAV_GROUPS) {
    nav.append(node('p', 'nav-group-label', group.label));
    for (const item of group.items) {
      const entry = button('', `nav-item${state.tab === item.id ? ' is-active' : ''}`, () => {
        goTo(item.id);
        render();
      });
      entry.append(node('span', `nav-icon ${item.icon}`), node('span', 'nav-label', item.label));
      if (item.badge) {
        entry.append(node('span', 'nav-badge', item.badge));
      }
      entry.dataset.tab = item.id;
      nav.append(entry);
    }
  }
  return nav;
}

function identityBlock() {
  const identity = node('div', 'admin-identity');
  const username = state.user?.username || 'Admin';
  const avatarUrl = state.user?.avatar;

  if (avatarUrl) {
    const avatar = node('img', 'identity-avatar');
    avatar.alt = username;
    avatar.src = avatarUrl;
    avatar.referrerPolicy = 'no-referrer';
    identity.append(avatar);
  } else {
    // No invented avatar: fall back to the real Discord initials.
    const initials = username
      .split(/[\s._-]+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0]?.toUpperCase() || '')
      .join('');
    identity.append(node('span', 'identity-avatar identity-initials', initials || 'A'));
  }

  const copy = node('div', 'identity-copy');
  copy.append(
    node('strong', '', username),
    node('span', '', 'Discord verified')
  );

  const logout = button('Sign out', 'button button-quiet', async () => {
    try {
      await request('/auth/logout', { method: 'POST', body: '{}' });
      window.location.assign('/');
    } catch (error) {
      notify(error.message, true);
    }
  });

  identity.append(copy, logout);
  return identity;
}

export function createShell(root) {
  let sidebar = root.querySelector('.sidebar');
  let main = root.querySelector('.admin-main');
  let content = root.querySelector('#admin-view');

  if (!sidebar || !main || !content) {
    root.replaceChildren();
    root.className = 'admin-app';

    sidebar = node('aside', 'sidebar');
    sidebar.append(brandBlock(), node('div', 'workspace-label', 'CONTROL CENTER'), navigation());

    const foot = node('div', 'sidebar-foot');
    foot.append(node('span', 'online-dot'), node('span', '', 'Node.js · PostgreSQL'));
    sidebar.append(foot);

    main = node('div', 'admin-main');
    const topbar = node('header', 'topbar');
    const crumb = node('div', 'topbar-title');
    crumb.id = 'topbar-crumb';
    const current = NAV_ITEMS.find((item) => item.id === state.tab);
    crumb.append(
      node('span', 'eyebrow', `${(state.data?.brand?.name || 'WAKTU SENJA').toUpperCase()} / ADMIN`),
      node('h1', '', current?.label || 'Dashboard')
    );
    topbar.append(crumb, identityBlock());

    content = node('div', 'page-content');
    content.id = 'admin-view';
    main.append(topbar, content);
    root.append(sidebar, main);
  } else {
    const crumb = main.querySelector('#topbar-crumb');
    if (crumb) {
      const current = NAV_ITEMS.find((item) => item.id === state.tab);
      crumb.replaceChildren(
        node('span', 'eyebrow', `${(state.data?.brand?.name || 'WAKTU SENJA').toUpperCase()} / ADMIN`),
        node('h1', '', current?.label || 'Dashboard')
      );
    }
  }

  // Seamlessly update navigation active state without refreshing or recreating sidebar
  const navItems = sidebar.querySelectorAll('.nav-item');
  for (const entry of navItems) {
    if (entry.dataset.tab === state.tab) {
      entry.classList.add('is-active');
    } else {
      entry.classList.remove('is-active');
    }
  }

  content.replaceChildren();
  return content;
}

