  donasi: 'Donation',
  staff: 'Staff Team'
};

export function getPath(object, path) {
  return path.split('.').reduce((current, key) => current?.[key], object);
}

export function setPath(object, path, value) {
  const parts = path.split('.');
  let current = object;
  for (const part of parts.slice(0, -1)) {
    if (!current[part] || typeof current[part] !== 'object') current[part] = {};
    current = current[part];
  }
  current[parts.at(-1)] = value;
}

export function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

export function walkLayout(layout, path, context, callback, ancestors = []) {
  if (!layout) return;
  if (layout.type === 'text') {
    if (layout.value?.trim()) {
      callback({ kind: 'text', path, value: layout.value, context, tag: 'text', ancestors });
    }
    return;
  }
  if (layout.type !== 'element') return;

  const nextContext = layout.attrs?.id && SECTIONS[layout.attrs.id]
    ? SECTIONS[layout.attrs.id]
    : layout.tag === 'nav' ? 'Navigation'
      : layout.tag === 'footer' ? 'Footer'
        : context;

  const nextAncestors = [
    ...ancestors,
    {
      tag: layout.tag,
      classes: String(layout.attrs?.class || '').split(/\s+/).filter(Boolean),
      id: layout.attrs?.id || ''
    }
  ];

  for (const [attribute, kind] of [['href', 'link'], ['src', 'media']]) {
    const value = layout.attrs?.[attribute];
    const isAnchorLink = layout.tag === 'a' && attribute === 'href';
    const isMediaSource = ['img', 'iframe'].includes(layout.tag) && attribute === 'src';
    if (typeof value === 'string' && value && (isAnchorLink || isMediaSource)) {
      callback({
        kind, path, attribute, value, context: nextContext,
        tag: layout.tag, alt: layout.attrs?.alt || '', ancestors: nextAncestors
      });
    }
  }

  (layout.children || []).forEach((child, index) => {
    walkLayout(child, [...path, index], nextContext, callback, nextAncestors);
  });
}

export function setBusy(busy) {
  state.busy = busy;
  document.querySelectorAll('[data-busy-action]').forEach((item) => {
    item.disabled = busy;
  });
}

export function goTo(tab) {
  state.tab = tab;
  state.contentPage = 0;
}

let rerender = () => {};

export function onRender(handler) {
  rerender = handler;
}

export function render() {
  rerender();
}

export async function saveSettings(patch) {
  setBusy(true);
  try {
    const result = await request('/api/admin/settings', {
      method: 'PUT',
      body: JSON.stringify({ settings: patch })
    });
    state.data.settings = result.settings;
    notify('Content settings saved to PostgreSQL.');
    await loadData(false);
    render();
  } catch (error) {
    notify(error.message, true);
  } finally {
    setBusy(false);
  }
}

export async function saveConfig(patch) {
  if (!Object.keys(patch).length) {
    notify('Nothing changed.');
    return;
  }
  setBusy(true);
  try {
    const result = await request('/api/admin/config', {
      method: 'PUT',
      body: JSON.stringify({ config: patch })
    });
    state.data.config = result.config;
    notify(`Configuration saved to .env — ${result.changed.length} key updated.`);
    await loadData(false);
    render();
  } catch (error) {
    notify(error.message, true);
  } finally {
    setBusy(false);
  }
}

export function configEntry(key) {
  const groups = state.data?.config?.groups || [];
  for (const group of groups) {
    const entry = group.keys.find((item) => item.key === key);
    if (entry) return entry;
  }
  return null;
}

export function configValue(key, fallback = '') {
  return configEntry(key)?.value ?? fallback;
}

export function saveForm(form, paths) {
  const patch = {};
  for (const path of paths) {
    const control = form.querySelector(`[data-path="${path}"]`);
    if (!control) continue;
    let value = control.type === 'checkbox' ? control.checked : control.value;
    if (control.type === 'number') value = Number(value);
    setPath(patch, path, value);
  }
  return saveSettings(patch);
}

export async function loadData(shouldRender = true) {
  state.data = await request('/api/admin/site');
  if (shouldRender) render();
}

