import { button, card, emptyState, node } from '../dom.js';
import { notify, request } from '../api.js';
import { render, state } from '../store.js';

export function renderAudit(view) {
  const panel = card('Activity history', 'Settings, content, and role changes are recorded in the database.');

  panel.append(button('Reload audit log', 'button button-secondary', async () => {
    try {
      const result = await request('/api/admin/audit');
