    title.append(node('strong', '', entry.action), node('span', 'muted', entry.actor_name || 'system'));
    row.append(title, node('time', 'audit-time', new Date(entry.created_at).toLocaleString('en-GB')));
    if (entry.details && Object.keys(entry.details).length) {
      row.append(node('p', 'audit-detail', JSON.stringify(entry.details)));
    }
    list.append(row);
  }

  panel.append(list);
  view.append(panel);
}

