import { button, card, emptyState, node } from '../dom.js';
import { notify, request } from '../api.js';
import {
  goTo,
  loadData,
  render,
  setBusy,
  state,
  walkLayout
} from '../store.js';

function collectEntries() {
  const entries = [];
  walkLayout(state.data?.layout, [], 'General', (entry) => entries.push(entry));
  return entries;
}

function isManagedBySettings(entry) {
  const classes = entry.ancestors.flatMap((item) => item.classes);
  const ids = entry.ancestors.map((item) => item.id);
  const managedText = ['wrapper-6', 'label-98', 'heading-73'];
  const managedLinks = ['link-8', 'link-18', 'link-19', 'link-20', 'link-22', 'link-27', 'link-31'];
  if (entry.kind === 'text'
      && (managedText.some((name) => classes.includes(name)) || ids.includes('player'))) {
    return true;
  }
  if (entry.kind === 'link' && managedLinks.some((name) => classes.includes(name))) return true;
  if (entry.kind === 'media' && ids.includes('player')) return true;
  return false;
}

function editorItems() {
  const mode = state.contentMode;
  const search = state.contentSearch.toLocaleLowerCase('en');
  return collectEntries().filter((entry) => {
    if (isManagedBySettings(entry)) return false;
    if (mode === 'text' && entry.kind !== 'text') return false;
    if (mode === 'url' && !['link', 'media'].includes(entry.kind)) return false;
    if (state.contentSection !== 'all' && entry.context !== state.contentSection) return false;
    const searchable = `${entry.context} ${entry.value} ${entry.tag} ${entry.alt || ''}`
      .toLocaleLowerCase('en');
    return searchable.includes(search);
  });
}

function entryKey(entry) {
  return `${entry.kind}:${entry.path.join('.')}:${entry.attribute || ''}`;
}

function renderEditorRows(host, pager, saveButton) {
  const entries = editorItems();
  const perPage = 40;
  const pages = Math.max(1, Math.ceil(entries.length / perPage));
  state.contentPage = Math.min(state.contentPage, pages - 1);
  const start = state.contentPage * perPage;
  const pageItems = entries.slice(start, start + perPage);
  host.replaceChildren();

  if (!pageItems.length) host.append(emptyState('No content matches the current filter.'));

  for (const entry of pageItems) {
    const key = entryKey(entry);
    const row = node('div', 'editor-row');
    const meta = node('div', 'editor-meta');
    const entryLabel = entry.kind === 'text'
      ? `Text · ${entry.tag}`
      : entry.kind === 'link' ? 'Link' : `Media · ${entry.tag}`;

    meta.append(node('span', 'editor-category', entry.context), node('strong', '', entryLabel));
    meta.append(node('small', '', `Path: ${entry.path.length ? entry.path.join('.') : 'root'}`));

    const current = state.changed.get(key)?.value ?? entry.value;
    const multiline = entry.kind === 'text' && (current.length > 95 || current.includes('\n'));
    const input = multiline ? node('textarea', 'control editor-value') : node('input', 'control editor-value');
    if (input.tagName === 'INPUT') input.type = 'text';
    if (input.tagName === 'TEXTAREA') input.rows = 2;
    input.value = current;
    input.maxLength = entry.kind === 'text' ? 4000 : 2048;

    input.addEventListener('input', () => {
      if (input.value === entry.value) state.changed.delete(key);
      else {
        state.changed.set(key, {
          kind: entry.kind === 'text' ? 'text' : 'attribute',
          path: entry.path,
          ...(entry.kind !== 'text' ? { attribute: entry.attribute } : {}),
          value: input.value
        });
      }
      updatePendingState(saveButton);
    });

    row.append(meta, input);
    if (entry.kind !== 'text' && entry.alt) row.append(node('small', 'editor-alt', `Alt: ${entry.alt}`));
    host.append(row);
  }

  pager.replaceChildren();
  const pageLabel = entries.length
    ? `${start + 1}–${Math.min(start + perPage, entries.length)} of ${entries.length}`
    : 'No results';
  pager.append(node('span', 'muted', pageLabel));

  const previous = button('', 'button button-quiet page-button', () => {
    state.contentPage = Math.max(0, state.contentPage - 1);
    renderEditorRows(host, pager, saveButton);
  });
  previous.append(node('span', 'ai-previous'));
  previous.setAttribute('aria-label', 'Previous page');
  previous.disabled = state.contentPage <= 0;

  const next = button('', 'button button-quiet page-button', () => {
    state.contentPage = Math.min(pages - 1, state.contentPage + 1);
    renderEditorRows(host, pager, saveButton);
  });
  next.append(node('span', 'ai-next'));
  next.setAttribute('aria-label', 'Next page');
  next.disabled = state.contentPage >= pages - 1;

  pager.append(previous, next);
  updatePendingState(saveButton);
}

function updatePendingState(saveButton) {
  const message = document.querySelector('.editor-changes');
  if (message) message.textContent = `${state.changed.size} unsaved change(s).`;
  saveButton.disabled = state.changed.size === 0 || state.changed.size > 300;
}

async function saveContent() {
  const changes = [...state.changed.values()];
  if (!changes.length) return notify('There are no changes to save.');
  if (changes.length > 300) return notify('Save at most 300 changes at a time.', true);

  setBusy(true);
  try {
    await request('/api/admin/layout', { method: 'PUT', body: JSON.stringify({ changes }) });
    state.changed.clear();
    await loadData(false);
    render();
    notify('Content saved. The public website will refresh automatically.');
  } catch (error) {
    notify(error.message, true);
  } finally {
    setBusy(false);
  }
  return undefined;
}

export function renderContent(view) {
  const panel = card(
    'Visual content editor',
    'Text, links, and media are stored in PostgreSQL. ' +
      'Core layout and animation remain part of the application code.'
  );

  const toolbar = node('div', 'editor-toolbar');
  const search = node('input', 'control editor-search');
  search.type = 'search';
  search.placeholder = 'Search text, buttons, URLs, or section names…';
  search.value = state.contentSearch;

  const rowsHost = node('div', 'editor-rows');
  const pager = node('div', 'editor-pager');
  const saveButton = button('Save changes', 'button button-primary', saveContent);
  saveButton.dataset.busyAction = 'true';

  search.addEventListener('input', () => {
    state.contentSearch = search.value;
    state.contentPage = 0;
    renderEditorRows(rowsHost, pager, saveButton);
  });

  const sectionFilter = node('select', 'control editor-filter');
  const sectionNames = [
    ['all', 'All sections'], ['Navigation', 'Navigation'], ['Home', 'Home'],
    ['How to Play', 'How to Play'], ['Rules', 'Rules'], ['FAQ', 'FAQ'],
    ['Donation', 'Donation'], ['Staff Team', 'Staff Team'], ['General', 'General'],
    ['Footer', 'Footer']
  ];
  for (const [value, label] of sectionNames) {
    const option = node('option', '', label);
    option.value = value;
    option.selected = state.contentSection === value;
    sectionFilter.append(option);
  }
  sectionFilter.addEventListener('change', () => {
    state.contentSection = sectionFilter.value;
    state.contentPage = 0;
    renderEditorRows(rowsHost, pager, saveButton);
  });

  const modeButtons = node('div', 'mode-switch');
  modeButtons.append(
    button('Text', `mode-button${state.contentMode === 'text' ? ' is-active' : ''}`, () => {
      state.contentMode = 'text';
      state.contentPage = 0;
      goTo('content');
      render();
    }),
    button('Links & media', `mode-button${state.contentMode === 'url' ? ' is-active' : ''}`, () => {
      state.contentMode = 'url';
      state.contentPage = 0;
      goTo('content');
      render();
    })
  );

  toolbar.append(search, sectionFilter, modeButtons);

  const hint = node('p', 'editor-hint',
    'Edit as needed, then press Save changes. External links are limited to safe protocols. ' +
    'A single save accepts up to 300 changes.');

  const bottom = node('div', 'editor-bottom');
  bottom.append(node('span', 'muted editor-changes', 'No local changes yet.'), pager, saveButton);

  panel.append(toolbar, hint, rowsHost, bottom);
  view.append(panel);
  renderEditorRows(rowsHost, pager, saveButton);
}

