  try {
    const result = await request('/api/admin/sync', { method: 'POST', body: '{}' });
    notify(`Sync finished: ${result.membersChecked} members checked, ${result.staffFound} staff detected.`);
    await loadData(false);
    render();
  } catch (error) {
    notify(error.message, true);
  } finally {
    setBusy(false);
  }
}

function renderTelemetry(view) {
  const telemetryCard = card(
    'Server Diagnostics & Infrastructure Telemetry',
    'Real-time operational health across application processes and linked services.'
  );

  const grid = node('div', 'telemetry-grid');

  const botUser = state.data?.discord?.botUser;
  const isGateway = Boolean(state.data?.discord?.gatewayConnected);

  const items = [
    { label: 'Database Engine', value: 'PostgreSQL (Active)', dot: 'is-ok' },
    { label: 'Discord Bot Client', value: botUser ? `@${botUser.username}` : (isGateway ? 'Online' : 'Offline'), dot: isGateway ? 'is-ok' : 'is-off' },
    { label: 'Web Server Engine', value: 'Node.js · Express', dot: 'is-ok' },
    { label: 'Active Admin Session', value: state.user?.username || 'Verified Admin', dot: 'is-ok' }
  ];

  for (const item of items) {
    const box = node('div', 'telemetry-item');
    box.append(
      node('span', 'telemetry-label', item.label),
      node('strong', 'telemetry-value', item.value)
    );
    grid.append(box);
  }

  telemetryCard.append(grid);
  view.append(telemetryCard);
}

function renderRecentActivity(view) {
  const audits = state.data?.audit || [];
  if (!audits.length) return;

  const panel = card(
    'Recent Administrative Activity',
    'Audit logs of configuration and role modifications on this server.'
  );

  const list = node('div', 'audit-list');
  const recent = audits.slice(0, 5);

  for (const item of recent) {
    const row = node('div', 'audit-row');
    const title = node('div', 'audit-title');
    title.append(
      node('strong', '', item.actor_name || 'System'),
      node('span', 'status-pill is-ok', item.action)
    );
    const time = node('small', 'audit-time', new Date(item.created_at).toLocaleString());
    row.append(title, time);

    if (item.details && Object.keys(item.details).length) {
      row.append(node('pre', 'audit-detail', JSON.stringify(item.details, null, 2)));
    }
    list.append(row);
  }

  panel.append(list);
  view.append(panel);
}

