import { button, card, checkbox, emptyState, field, node, statCard } from '../dom.js';
import { notify, request } from '../api.js';
import { loadData, render, setBusy, state } from '../store.js';

const CATEGORY_META = {
  founders: { icon: '👑', color: '#f59e0b', label: 'Founders' },
  management: { icon: '💼', color: '#a855f7', label: 'Management' },
  developers: { icon: '💻', color: '#38bdf8', label: 'Developers' },
  'head-admin': { icon: '🛡️', color: '#e59da1', label: 'Head Admin' },
  admin: { icon: '⚖️', color: '#10b981', label: 'Administrators' },
  helper: { icon: '🤝', color: '#14b8a6', label: 'Helper Team' },
  'staff-discord': { icon: '💬', color: '#6366f1', label: 'Discord Staff' },
  'assets-graphics': { icon: '🎨', color: '#ec4899', label: 'Assets & Graphics' },
  'brand-ambassador': { icon: '⭐', color: '#f97316', label: 'Brand Ambassador' }
};

let staffFilterQuery = '';

async function syncNow() {
  setBusy(true);
  try {
    const result = await request('/api/admin/sync', { method: 'POST', body: '{}' });
    notify(`Sync finished: ${result.membersChecked} members checked, ${result.staffFound} staff detected.`);
    await loadData(false);
    render();
  } catch (error) {
    notify(error.message, true);
  } finally {
    setBusy(false);
  }
}

async function removeRole(roleId, title) {
  if (!window.confirm(`Remove ${title} (${roleId}) from .env and the database?`)) return;
  setBusy(true);
  try {
    await request(`/api/admin/roles/${encodeURIComponent(roleId)}`, { method: 'DELETE' });
    notify('Role removed from .env and the database.');
    await loadData(false);
    render();
  } catch (error) {
    notify(error.message, true);
  } finally {
    setBusy(false);
  }
}

function renderStatsHeader(view) {
  const groups = state.data?.config?.roles || [];
  const totalRoles = groups.reduce((acc, g) => acc + (g.ids?.length || 0), 0);
  const totalStaff = state.data?.live?.staff ?? 0;
  const isOnline = Boolean(state.data?.discord?.gatewayConnected);

  const grid = node('div', 'stat-grid');
  grid.append(
    statCard('CONFIGURED ROLES', totalRoles, 'Active in .env configuration', 'ai-roles'),
    statCard('SYNCED STAFF', totalStaff, 'Live members from Discord guild', 'ai-users'),
    statCard('DISCORD GATEWAY', isOnline ? 'Online' : 'Offline', isOnline ? 'Bot WebSocket connected' : 'Connecting...', 'ai-shield'),
    statCard('ACTIVE SECTIONS', groups.filter((g) => g.ids?.length).length, 'Departments mapped', 'ai-check')
  );
  view.append(grid);
}

function renderAddRoleForm(view) {
  const panel = card(
    'Add Discord Role Mapping',
    'Register a role ID from your Discord server. The ID will be written directly to .env and synchronized with PostgreSQL.'
  );

  const form = node('form', 'role-form');
  form.append(
    field('Discord Role ID', '', {
      path: 'roleId',
      required: true,
      placeholder: '17–20 digit snowflake ID (e.g. 1566584664573870140)'
    }),
    field('Public Display Title', '', {
      path: 'title',
      required: true,
      placeholder: 'e.g. Head Admin, Lead Developer'
    }),
    field('Department Category', 'staff', {
      path: 'section',
      type: 'select',
      options: [
        { label: '👑 Founders', value: 'founders' },
        { label: '💼 Management', value: 'management' },
        { label: '💻 Developer', value: 'developers' },
        { label: '🛡️ Head Admin', value: 'head-admin' },
        { label: '⚖️ Admin Team', value: 'admin' },
        { label: '🤝 Helper Team', value: 'helper' },
        { label: '💬 Discord Staff', value: 'staff-discord' },
        { label: '🎨 Asset & Graphics', value: 'assets-graphics' },
        { label: '⭐ Brand Ambassador', value: 'brand-ambassador' },
        { label: '🛡️ Other staff', value: 'staff' }
      ]
    }),
    field('Priority Order (Lower displays first)', 100, {
      path: 'sortOrder',
      type: 'number',
      min: -10000,
      max: 10000
    }),
    checkbox('Enable role mapping immediately', true, 'enabled'),
    button('Add & Sync Role', 'button button-primary', null, 'submit')
  );

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const value = (path) => form.querySelector(`[data-path="${path}"]`);
    const data = {
      roleId: value('roleId').value.trim(),
      title: value('title').value.trim(),
      section: value('section').value,
      sortOrder: Number(value('sortOrder').value || 100),
      enabled: value('enabled').checked
    };

    setBusy(true);
    try {
      const result = await request('/api/admin/roles', { method: 'POST', body: JSON.stringify(data) });
      const message = result.sync?.warning
        ? `Role saved to .env; sync postponed: ${result.sync.warning}`
        : result.gatewayConnected
          ? `Role saved to .env. ${result.sync?.staffFound ?? 0} staff detected after sync.`
          : 'Role saved to .env. The bot is offline; staff will sync once the Gateway connects.';
      notify(message, Boolean(result.sync?.warning));
      await loadData(false);
      render();
    } catch (error) {
      notify(error.message, true);
    } finally {
      setBusy(false);
    }
  });

  panel.append(form);
  view.append(panel);
}

function renderDepartmentRoster(view) {
  const panel = card(
    'Discord Roles & Live Staff Roster',
    'Real-time view of Discord roles mapped in .env alongside synchronized staff members.'
  );

  const topBar = node('div', 'quick-actions', '');
  topBar.style.marginBottom = '18px';
  topBar.append(
    button('Sync Discord Staff Now', 'button button-primary', syncNow)
  );
  panel.append(topBar);

  const groups = state.data?.config?.roles || [];
  const allMembers = state.data?.live?.members || [];

  const grid = node('div', 'role-categories-grid');

  for (const group of groups) {
    const meta = CATEGORY_META[group.key] || { icon: '🛡️', color: '#c97f83', label: group.label };
    const membersInGroup = allMembers.filter((m) => m.section === group.key);

    const cardEl = node('article', 'role-cat-card');
    cardEl.style.borderTop = `2px solid ${meta.color}`;

    // Header
    const head = node('div', 'role-cat-header');
    const titleArea = node('div', 'role-cat-title');
    const iconEl = node('span', 'role-cat-icon', meta.icon);
    iconEl.style.color = meta.color;
    iconEl.style.boxShadow = `0 0 14px ${meta.color}33`;

    const titleText = node('div');
    titleText.append(
      node('strong', '', group.label),
      node('code', '', group.env)
    );
    titleArea.append(iconEl, titleText);

    const countBadge = node(
      'span',
      `role-cat-badge ${membersInGroup.length > 0 ? 'is-positive' : ''}`,
      `${membersInGroup.length} Staff`
    );
    head.append(titleArea, countBadge);

    // Body: Role ID chips
    const body = node('div', 'role-cat-body');
    const chipsWrap = node('div', 'role-cat-chips');

    if (!group.ids.length) {
      chipsWrap.append(node('span', 'muted', 'No role ID assigned in .env.'));
    } else {
      for (const roleId of group.ids) {
        const chip = node('span', 'role-chip');
        chip.append(node('code', '', roleId));
        chip.title = 'Click to copy ID';
        chip.style.cursor = 'pointer';
        chip.addEventListener('click', (e) => {
          if (e.target.closest('.role-chip-remove')) return;
          navigator.clipboard?.writeText(roleId);
          notify(`Copied role ID: ${roleId}`);
        });

        const remove = button('', 'role-chip-remove', (e) => {
          e.stopPropagation();
          removeRole(roleId, group.label);
        });
        remove.append(node('span', 'ai-close'));
        remove.title = `Remove ${roleId}`;
        chip.append(remove);
        chipsWrap.append(chip);
      }
    }
    body.append(chipsWrap);

    // Live Staff Member Preview
    const rosterSection = node('div', 'member-roster-preview');
    const rosterHead = node('div', 'roster-preview-title');
    rosterHead.append(
      node('span', '', 'Live Discord Members'),
      node('span', 'muted', `${membersInGroup.length} detected`)
    );
    rosterSection.append(rosterHead);

    if (membersInGroup.length > 0) {
      const rosterGrid = node('div', 'roster-preview-grid');
      for (const member of membersInGroup) {
        const memberCard = node('div', 'staff-mini-card');
        const avatarImg = node('img', 'staff-mini-avatar');
        avatarImg.src = member.avatar || '/assets/brand/logo.gif';
        avatarImg.alt = member.name || member.username;
        avatarImg.loading = 'lazy';

        const copyDiv = node('div', 'staff-mini-copy');
        copyDiv.append(
          node('strong', 'staff-mini-name', member.name || member.username),
          node('small', 'staff-mini-handle', member.username ? `@${member.username}` : member.title)
        );

        memberCard.append(avatarImg, copyDiv);
        rosterGrid.append(memberCard);
      }
      rosterSection.append(rosterGrid);
    } else {
      rosterSection.append(node('p', 'muted', 'No staff currently hold this role in Discord.'));
    }

    body.append(rosterSection);
    cardEl.append(head, body);
    grid.append(cardEl);
  }

  panel.append(grid);
  view.append(panel);
}

function renderAllStaffDirectory(view) {
  const allMembers = state.data?.live?.members || [];
  if (!allMembers.length) return;

  const panel = card(
    'Staff Directory & Live Discord Roster',
    'Full searchable directory of all team members synchronized from Discord.'
  );

  const searchBox = node('input', 'control');
  searchBox.type = 'text';
  searchBox.placeholder = 'Search staff by name, handle, or title…';
  searchBox.value = staffFilterQuery;
  searchBox.style.maxWidth = '360px';
  searchBox.style.marginBottom = '16px';

  const listContainer = node('div', 'role-list');

  function renderList() {
    listContainer.replaceChildren();
    const query = staffFilterQuery.toLowerCase().trim();
    const filtered = allMembers.filter((m) => {
      if (!query) return true;
      return (
        m.name?.toLowerCase().includes(query) ||
        m.username?.toLowerCase().includes(query) ||
        m.title?.toLowerCase().includes(query) ||
        m.section?.toLowerCase().includes(query)
      );
    });

    if (!filtered.length) {
      listContainer.append(emptyState('No staff members match your search query.'));
      return;
    }

    for (const member of filtered) {
      const row = node('div', 'role-row');

      const avatar = node('img', 'staff-mini-avatar');
      avatar.src = member.avatar || '/assets/brand/logo.gif';
      avatar.alt = member.name || member.username;
      avatar.style.width = '36px';
      avatar.style.height = '36px';

      const detail = node('div', 'role-detail');
      detail.append(
        node('strong', '', member.name || member.username),
        node('span', 'muted', `@${member.username} · ID: ${member.id}`),
        node('span', 'role-section', `${member.title || 'Staff'} · Section: ${member.section}`)
      );

      const statusBadge = node('span', 'status-pill is-ok', 'VERIFIED');
      row.append(avatar, detail, statusBadge);
      listContainer.append(row);
    }
  }

  searchBox.addEventListener('input', (e) => {
    staffFilterQuery = e.target.value;
    renderList();
  });

  renderList();
  panel.append(searchBox, listContainer);
  view.append(panel);
}

export function renderRoles(view) {
  renderStatsHeader(view);
  renderDepartmentRoster(view);
  renderAddRoleForm(view);
  renderAllStaffDirectory(view);
}

