import { button, card, checkbox, field, node } from '../dom.js';
import { notify } from '../api.js';
import {
  configEntry,
  configValue,
  deepClone,
  getPath,
  saveConfig,
  saveForm,
  saveSettings,
  setPath,
  state
} from '../store.js';

const LOCALE_OPTIONS = [
  ['en', 'English'], ['id', 'Bahasa Indonesia'], ['ms', 'Bahasa Melayu'],
  ['ja', '日本語'], ['ko', '한국어'], ['de', 'Deutsch'],
  ['tr', 'Türkçe'], ['hi', 'हिन्दी'], ['ru', 'Русский']
];

function configControl(entry) {
  if (!entry) return node('span', 'muted', 'Missing key');
  if (entry.locked) {
    return node('span', 'config-locked', entry.hasValue ? 'Stored in .env (locked)' : 'Not set (locked)');
  }

  let input;
  if (entry.type === 'boolean') {
    input = node('input');
    input.type = 'checkbox';
    input.checked = String(entry.value).toLowerCase() === 'true';
  } else if (entry.type === 'textarea') {
    input = node('textarea', 'control');
    input.rows = 3;
    input.value = entry.value;
  } else if (entry.type === 'locale') {
    input = node('select', 'control');
    for (const [value, label] of LOCALE_OPTIONS) {
      const option = node('option', '', label);
      option.value = value;
      option.selected = entry.value === value;
      input.append(option);
    }
  } else if (entry.type === 'number') {
    input = node('input', 'control');
    input.type = 'number';
    input.value = entry.value;
  } else if (entry.type === 'color') {
    input = node('input', 'control config-color');
    input.type = 'color';
    input.value = entry.value || '#000000';
  } else {
    input = node('input', 'control');
    input.type = 'text';
    input.value = entry.value;
  }

  input.dataset.configKey = entry.key;
  return input;
}

function configRow(key, labelText, hint = '') {
  const entry = configEntry(key);
  const wrap = node('label', 'field');
  wrap.append(node('span', 'field-label', labelText || key));
  wrap.append(configControl(entry));
  if (hint) wrap.append(node('small', 'field-hint', hint));
  return wrap;
}

function collectConfig(form) {
  const patch = {};
  for (const input of form.querySelectorAll('[data-config-key]')) {
    patch[input.dataset.configKey] = input.type === 'checkbox'
      ? String(input.checked)
      : input.value;
  }
  return patch;
}

function configForm(keys) {
  const form = node('form', 'settings-form');
  for (const item of keys) {
    form.append(Array.isArray(item) ? configRow(item[0], item[1], item[2]) : configRow(item));
  }
  form.append(button('Save to .env', 'button button-primary', () => saveConfig(collectConfig(form))));
  return form;
}

