function getFaqQuestions(layout) {
  const allowed = new Set(Array.from({ length: 11 }, (_, index) => `button-${index + 19}`));
  const result = [];

  const readText = (item) => {
    if (!item) return '';
    if (item.type === 'text') return String(item.value || '').trim();
    return (item.children || []).map(readText).filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
  };

  const findElement = (item, predicate) => {
    if (!item || item.type !== 'element') return null;
    if (predicate(item)) return item;
    for (const child of item.children || []) {
      const found = findElement(child, predicate);
      if (found) return found;
    }
    return null;
  };

  const visit = (item) => {
    if (!item || item.type !== 'element') return;
    const className = String(item.attrs?.class || '');
    if (allowed.has(className)) {
      const wrapper = (item.children || []).find((child) => child.type === 'element' && child.tag === 'div');
      const categoryNode = (wrapper?.children || []).find((child) =>
        child.type === 'element' && child.tag === 'div');
      const titleNode = findElement(item, (child) => child.tag === 'h4');
      result.push({
        category: readText(categoryNode) || `Category ${result.length + 1}`,
        title: readText(titleNode) || `Question ${result.length + 1}`
      });
    }
    for (const child of item.children || []) visit(child);
  };

  visit(layout);
  return result.slice(0, 11);
}

export function renderFaq(view) {
  const settings = deepClone(state.data.settings);
