// Real progress loader. Every step is tied to an actual resource or request,
// never to a timer. The curtain only opens once the page is genuinely ready.

const DEFAULT_WEIGHTS = {
  styles: 12,
  fonts: 10,
  logo: 6,
  locale: 10,
  data: 20,
  render: 10,
  images: 22,
  video: 10
};

const DEFAULT_LABELS = {
  styles: 'Loading styles',
  fonts: 'Preparing typography',
  logo: 'Loading brand',
  locale: 'Loading language',
  data: 'Fetching city data',
  render: 'Building layout',
  images: 'Loading artwork',
  video: 'Buffering showreel',
  ready: 'Welcome to Waktu Senja'
};

export function stylesReady() {
  const links = [...document.querySelectorAll('link[rel="stylesheet"]')];
  return Promise.all(links.map((link) => {
    if (link.sheet) return Promise.resolve();
    return new Promise((resolve) => {
      link.addEventListener('load', resolve, { once: true });
      link.addEventListener('error', resolve, { once: true });
      window.setTimeout(resolve, 4000);
    });
  }));
}

export function imageReady(image) {
  if (!image) return Promise.resolve();
  if (image.complete && image.naturalWidth > 0) return Promise.resolve();
  return new Promise((resolve) => {
    image.addEventListener('load', resolve, { once: true });
    image.addEventListener('error', resolve, { once: true });
    window.setTimeout(resolve, 4000);
  });
}

// The hero YouTube iframe is part of the real load: the curtain only opens once
// the showreel document has actually loaded. A hard timeout keeps a slow or
// blocked embed from freezing the loader.
export function frameReady(frame) {
  if (!frame || frame.dataset.preloadDone === '1') return Promise.resolve();
  return new Promise((resolve) => {
    const done = () => {
      if (frame.dataset.preloadDone === '1') return;
      frame.dataset.preloadDone = '1';
      resolve();
    };
    frame.addEventListener('load', done, { once: true });
    frame.addEventListener('error', done, { once: true });
    window.setTimeout(done, 6000);
  });
}

// The player reports its own state, so the loader waits for the real outcome:
// the showreel playing, or the player refusing it. Either way the page opens.
export function heroVideoReady(frame) {
  if (!frame) return Promise.resolve();

  const state = document.documentElement.dataset.heroVideoState;
  if (state === 'ready' || state === 'failed') return Promise.resolve();

  return new Promise((resolve) => {
    let settled = false;

    const finish = () => {
      if (settled) return;
      settled = true;
      document.removeEventListener('ime:hero-video', onState);
      resolve();
    };

    const onState = (event) => {
      if (event.detail?.state === 'ready' || event.detail?.state === 'failed') finish();
    };

    document.addEventListener('ime:hero-video', onState);
    frame.addEventListener('load', finish, { once: true });
    frame.addEventListener('error', finish, { once: true });
    window.setTimeout(finish, 8000);
  });
}

export function imagesReady(scope = document) {
  const images = [...scope.querySelectorAll('img')];
  return Promise.all(images.map((image) => imageReady(image)));
}

export function createPreloader(options = {}) {
  const root = document.getElementById('preloader');
  const bar = root?.querySelector('.preloader-bar');
  const percentEl = root?.querySelector('.preloader-percent');
  const statusEl = root?.querySelector('.preloader-status');

  if (!root || !bar || !percentEl || !statusEl) {
    return {
      track: (_name, promise) => Promise.resolve(promise),
      mark: () => {},
      stepFraction: () => {},
      status: () => {},
      complete: async () => {},
      fail: () => {}
    };
  }

  const weights = { ...DEFAULT_WEIGHTS, ...(options.weights || {}) };
  const labels = { ...DEFAULT_LABELS, ...(options.labels || {}) };
  const planned = new Set(options.tasks || Object.keys(weights));
  const totalWeight = [...planned].reduce((sum, name) => sum + (weights[name] || 0), 0) || 100;
  const minimumMs = Number(options.minimumMs ?? 400);
  const startedAt = performance.now();

  const taskProgress = new Map();
  let targetPercent = 5;
  let displayedPercent = 0;
  let animationFrameId = null;
  let isFinished = false;
  let completionResolver = null;

  function recomputeTarget() {
    let accumulated = 0;
    for (const name of planned) {
      const weight = weights[name] || 0;
      const fraction = taskProgress.get(name) || 0;
      accumulated += weight * fraction;
    }
    const computed = 5 + (accumulated / totalWeight) * 95;
    targetPercent = Math.min(100, Math.max(targetPercent, computed));
  }

  function setStatus(text) {
    if (text && statusEl) statusEl.textContent = text;
  }

  let lastTime = performance.now();

  function animate(now = performance.now()) {
    const elapsed = Math.min(Math.max(now - lastTime, 0), 200); // ms
    lastTime = now;
    const deltaRatio = Math.max(0.5, Math.min(elapsed / 16.67, 10)); // Normalized to 60fps frame duration

    if (displayedPercent < targetPercent) {
      const distance = targetPercent - displayedPercent;
      // Damped smooth velocity normalized by delta time so background tabs / throttled frames don't stall
      const baseStep = Math.min(Math.max(distance * 0.085, 0.08), 0.85);
      const step = baseStep * deltaRatio;
      displayedPercent = Math.min(targetPercent, displayedPercent + step);
    } else if (displayedPercent > targetPercent) {
      displayedPercent = targetPercent;
    }

    bar.style.width = `${displayedPercent.toFixed(2)}%`;
    percentEl.textContent = `${Math.floor(displayedPercent)}%`;

    if (isFinished && displayedPercent >= 99.7) {
      displayedPercent = 100;
      bar.style.width = '100%';
      percentEl.textContent = '100%';
      animationFrameId = null;
      if (completionResolver) completionResolver();
      return;
    }

    animationFrameId = requestAnimationFrame(animate);
  }

  // Start continuous smooth animation loop
  animationFrameId = requestAnimationFrame(animate);

  function mark(name) {
    if (!planned.has(name)) return;
    taskProgress.set(name, 1.0);
    recomputeTarget();
  }

  function stepFraction(name, current, total) {
    if (!planned.has(name)) return;
    const fraction = Math.min(1.0, Math.max(0, current / (total || 1)));
    taskProgress.set(name, fraction);
    recomputeTarget();
  }

  async function track(name, promise) {
    if (labels[name]) setStatus(labels[name]);
    try {
      await promise;
    } catch {
      // Handled gracefully so slow/blocked resources don't break the loader
    }
    mark(name);
  }

  function waitForBarCompletion() {
    return new Promise((resolve) => {
      if (displayedPercent >= 99.85) {
        resolve();
      } else {
        completionResolver = resolve;
      }
    });
  }

  async function complete() {
    if (isFinished) return;
    isFinished = true;

    for (const name of planned) taskProgress.set(name, 1.0);
    recomputeTarget();

    const elapsed = performance.now() - startedAt;
    if (elapsed < minimumMs) {
      await new Promise((resolve) => window.setTimeout(resolve, minimumMs - elapsed));
    }

    await waitForBarCompletion();
    setStatus(labels.ready || 'Ready');

    // Brief pause at 100% so user sees completion
    await new Promise((resolve) => window.setTimeout(resolve, 260));

    document.body.classList.remove('is-loading');
    root.classList.add('is-opening');

    window.setTimeout(() => {
      root.classList.add('is-done');
      window.setTimeout(() => {
        if (animationFrameId) cancelAnimationFrame(animationFrameId);
        root.remove();
      }, 550);
    }, 1150);
  }

  function fail(message) {
    isFinished = true;
    setStatus(message || 'Something went wrong');
    percentEl.textContent = '—';
    bar.style.width = '100%';
    bar.style.opacity = '0.4';
    window.setTimeout(() => {
      document.body.classList.remove('is-loading');
      root.classList.add('is-opening');
      window.setTimeout(() => {
        if (animationFrameId) cancelAnimationFrame(animationFrameId);
        root.remove();
      }, 1300);
    }, 900);
  }

  return { track, mark, stepFraction, status: setStatus, complete, fail };
}

