import { DEFAULT_CONNECT_COMMAND } from './config.js';
import { el, qs, qsa } from './dom.js';
import { formatNotice, getLocale, listLocales, setLocale, t } from './i18n.js';
import { showNotice } from './notices.js';

// The original layout only renders a language list inside the mobile overlay,
// so the desktop trigger gets its own dropdown built from the locale catalog.
const FLAG_TO_LOCALE = {
  US: 'en',
  ID: 'id',
  MY: 'ms'
};

let globalActionsWired = false;
let isAudioPlaying = false;
let onLocaleRequested = () => {};

export function setLocaleHandler(handler) {
  onLocaleRequested = typeof handler === 'function' ? handler : () => {};
}

function languageTrigger() {
  return qs('.button-2');
}

function closeLanguageMenu() {
  const wrapper = languageTrigger()?.closest('.wrapper-9');
  wrapper?.classList.remove('ime-language-open');
  languageTrigger()?.setAttribute('aria-expanded', 'false');
}

async function applyLocale(code) {
  const applied = await setLocale(code);
  if (applied !== code) return;
  closeLanguageMenu();
  markActiveLanguage();
  onLocaleRequested(code);
  const entry = listLocales().find((item) => item.code === code);
  showNotice(formatNotice('language.switched', { language: entry?.label || code }));
}

function buildLanguageMenu(wrapper) {
  const existing = wrapper.querySelector('.ime-language-menu');
  if (existing) existing.remove();

  const menu = el('div', 'ime-language-menu');
  menu.setAttribute('role', 'menu');

  for (const entry of listLocales()) {
    const option = el('button', 'ime-language-option');
    option.type = 'button';
    option.dataset.locale = entry.code;
    option.setAttribute('role', 'menuitem');

    const flag = el('img', 'ime-language-flag');
    flag.src = entry.flag;
    flag.alt = '';
    flag.width = 20;
    flag.height = 14;
    flag.loading = 'lazy';

    option.append(
      flag,
      el('span', 'ime-language-name', entry.label)
    );
    option.addEventListener('click', (event) => {
      event.stopPropagation();
      applyLocale(entry.code);
    });
    menu.append(option);
  }

  wrapper.append(menu);
  return menu;
}

function markActiveLanguage() {
  const code = getLocale();
  qsa('.ime-language-option').forEach((option) => {
    option.classList.toggle('is-active', option.dataset.locale === code);
  });
  qsa('.wrapper-23 button').forEach((option) => {
    const label = option.querySelector('span')?.textContent.trim().toUpperCase();
    option.classList.toggle('ime-language-active', FLAG_TO_LOCALE[label] === code);
  });

  const entry = listLocales().find((item) => item.code === code);
  if (!entry) return;
  const currentCode = qs('.button-2 .label-10');
  if (currentCode) currentCode.textContent = entry.short || entry.code.toUpperCase();
  const flag = qs('.button-2 .image-2');
  if (flag) {
    flag.src = entry.flag;
    flag.alt = entry.short || entry.code.toUpperCase();
  }
}

function wireLanguageSelector() {
  const trigger = languageTrigger();
  const wrapper = trigger?.closest('.wrapper-9');
  if (!trigger || !wrapper) return;

  buildLanguageMenu(wrapper);
  trigger.setAttribute('aria-expanded', 'false');
  trigger.setAttribute('aria-label', t('language.trigger'));
  trigger.addEventListener('click', (event) => {
    event.stopPropagation();
    trigger.classList.remove('ime-button-clicked');
    void trigger.offsetWidth;
    trigger.classList.add('ime-button-clicked');
    const opened = wrapper.classList.toggle('ime-language-open');
    trigger.setAttribute('aria-expanded', String(opened));
  });

  // The mobile overlay keeps its own list; filter to supported languages only.
  qsa('.wrapper-23 button').forEach((option) => {
    const label = option.querySelector('span')?.textContent.trim().toUpperCase();
    if (!FLAG_TO_LOCALE[label]) {
      option.remove();
      return;
    }
    option.addEventListener('click', (event) => {
      event.stopPropagation();
      const code = FLAG_TO_LOCALE[label];
      if (code) applyLocale(code);
    });
  });

  markActiveLanguage();
}

function smoothScrollTo(targetY, duration = 650) {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    window.scrollTo(0, targetY);
    return;
  }
  const startY = window.pageYOffset;
  const difference = targetY - startY;
  if (Math.abs(difference) < 2) return;
  const startTime = performance.now();

  function step(currentTime) {
    const elapsed = currentTime - startTime;
    const progress = Math.min(elapsed / duration, 1);
    // Smooth ease-in-out cubic animation
    const ease = progress < 0.5
      ? 4 * progress * progress * progress
      : 1 - Math.pow(-2 * progress + 2, 3) / 2;

    window.scrollTo(0, startY + difference * ease);

    if (progress < 1) {
      window.requestAnimationFrame(step);
    }
  }

  window.requestAnimationFrame(step);
}

function wireGlobalListeners() {
  if (globalActionsWired) return;

  // Admin-configured destinations run in the capture phase so they win over default actions.
  document.addEventListener('click', (event) => {
    const target = event.target instanceof Element ? event.target.closest('button[data-destination]') : null;
    const destination = target?.dataset.destination;
    if (!target || !destination) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (destination.startsWith('#')) {
      const section = document.getElementById(destination.slice(1));
      if (section) {
        const navbar = document.querySelector('.nav') || document.querySelector('.wrapper-4');
        const navHeight = navbar ? Math.min(navbar.offsetHeight, 100) : 80;
        const targetTop = destination === '#home' ? 0 : section.getBoundingClientRect().top + window.pageYOffset - navHeight - 16;
        smoothScrollTo(Math.max(0, targetTop), 650);
        history.replaceState(null, '', destination);
      }
      return;
    }
    window.location.assign(destination);
  }, true);

  // Smooth scroll handler for all internal anchor links (navbar, mobile drawer, logo, footer)
  document.addEventListener('click', (event) => {
    const link = event.target instanceof Element ? event.target.closest('a[href*="#"]') : null;
    if (!link) return;

    const href = link.getAttribute('href');
    if (!href || href === '#' || href.startsWith('javascript:')) return;

    let hash = '';
    try {
      const url = new URL(link.href, window.location.href);
      if (url.origin === window.location.origin && url.pathname === window.location.pathname && url.hash) {
        hash = url.hash;
      }
    } catch {
      if (href.startsWith('#')) hash = href;
    }

    if (!hash) return;

    const target = hash === '#home' || hash === '#'
      ? document.getElementById('home') || document.body
      : document.querySelector(hash);

    if (target) {
      event.preventDefault();

      // Close mobile drawer if open
      const mobileNav = document.querySelector('nav.nav');
      if (mobileNav?.classList.contains('ime-menu-open')) {
        mobileNav.classList.remove('ime-menu-open');
        document.querySelector('.button-3')?.setAttribute('aria-expanded', 'false');
      }

      // Calculate position accounting for the floating navbar
      const navbar = document.querySelector('.nav') || document.querySelector('.wrapper-4');
      const navHeight = navbar ? Math.min(navbar.offsetHeight, 100) : 80;
      const targetTop = target === document.body || target === document.getElementById('home')
        ? 0
        : target.getBoundingClientRect().top + window.pageYOffset - navHeight - 16;

      smoothScrollTo(Math.max(0, targetTop), 650);

      if (window.history.pushState) {
        window.history.pushState(null, '', hash);
      } else {
        window.location.hash = hash;
      }
    }
  });

  document.addEventListener('click', (event) => {
    const wrapper = languageTrigger()?.closest('.wrapper-9');
    if (!wrapper || !wrapper.classList.contains('ime-language-open')) return;
    if (event.target instanceof Node && !wrapper.contains(event.target)) closeLanguageMenu();
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeLanguageMenu();
  });

  globalActionsWired = true;
}

async function copyConnectionCommand(button) {
  const configured = qs('.label-28')?.textContent.trim() || DEFAULT_CONNECT_COMMAND;
  const command = /^connect\s+/i.test(configured) ? configured : `connect ${configured}`;
  try {
    await navigator.clipboard.writeText(command);
    showNotice(t('notice.commandCopied'));
    if (button?.classList.contains('button-14')) {
      const textNode = [...button.childNodes].find((node) =>
        node.nodeType === Node.TEXT_NODE && node.textContent.trim());
      if (textNode) {
        const original = textNode.textContent;
        textNode.textContent = ` ${t('notice.copied')}`;
        window.setTimeout(() => {
          if (textNode.isConnected) textNode.textContent = original;
        }, 1800);
      }
    }
  } catch {
    showNotice(`${t('notice.copyManually')} ${command}`);
  }
}

function wireCopyButtons() {
  for (const selector of ['.button-14', '.button-13']) {
    const button = qs(selector);
    button?.addEventListener('click', (event) => copyConnectionCommand(event.currentTarget));
  }
}

function wireMobileMenu() {
  const menuButton = qs('.button-3');
  if (!menuButton) return;

  // Insert 3-bar animated hamburger structure if not already present
  if (!menuButton.querySelector('.ime-hamburger')) {
    const hamburger = document.createElement('span');
    hamburger.className = 'ime-hamburger';
    hamburger.setAttribute('aria-hidden', 'true');
    hamburger.innerHTML = `
      <span class="ime-hamburger-line ime-line-top"></span>
      <span class="ime-hamburger-line ime-line-mid"></span>
      <span class="ime-hamburger-line ime-line-bot"></span>
    `;
    menuButton.appendChild(hamburger);
  }

  if (menuButton.dataset.wiredMenu === '1') return;
  menuButton.dataset.wiredMenu = '1';

  menuButton.addEventListener('click', () => {
    // Replay tactile spring bounce animation
    menuButton.classList.remove('ime-menu-clicked');
    void menuButton.offsetWidth;
    menuButton.classList.add('ime-menu-clicked');

    const nav = menuButton.closest('nav');
    const opened = nav?.classList.toggle('ime-menu-open') || false;
    menuButton.setAttribute('aria-expanded', String(opened));
    menuButton.setAttribute('aria-label', opened ? 'Close Menu' : 'Open Menu');
  });

  qsa('.wrapper-11 a').forEach((link) => {
    link.addEventListener('click', () => {
      menuButton.closest('nav')?.classList.remove('ime-menu-open');
      menuButton.setAttribute('aria-expanded', 'false');
      menuButton.setAttribute('aria-label', 'Open Menu');
    });
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      const nav = menuButton.closest('nav');
      if (nav?.classList.contains('ime-menu-open')) {
        nav.classList.remove('ime-menu-open');
        menuButton.setAttribute('aria-expanded', 'false');
        menuButton.setAttribute('aria-label', 'Open Menu');
      }
    }
  });
}

function suppressMediaSession() {
  if (typeof navigator !== 'undefined' && 'mediaSession' in navigator) {
    try {
      navigator.mediaSession.metadata = null;
      navigator.mediaSession.playbackState = 'none';
      const actions = ['play', 'pause', 'previoustrack', 'nexttrack', 'seekbackward', 'seekforward', 'seekto', 'stop'];
      for (const act of actions) {
        try {
          navigator.mediaSession.setActionHandler(act, null);
        } catch {}
      }
    } catch {}
  }
}

let musicLoopListenerWired = false;
function wireMusicLoop() {
  if (musicLoopListenerWired) return;
  window.addEventListener('message', (event) => {
    if (typeof event.data !== 'string') return;
    try {
      const data = JSON.parse(event.data);
      if (data.event === 'infoDelivery' && data.info?.playerState === 0) {
        const frame = document.getElementById('music-player');
        if (frame?.contentWindow && isAudioPlaying) {
          frame.contentWindow.postMessage(JSON.stringify({ event: 'command', func: 'seekTo', args: [0, true] }), '*');
          frame.contentWindow.postMessage(JSON.stringify({ event: 'command', func: 'playVideo', args: [] }), '*');
        }
      }
    } catch {}
  });
  musicLoopListenerWired = true;
}

function updateAudioState(button, playing) {
  if (!button) return;
  button.classList.toggle('is-playing', playing);
  button.classList.toggle('ime-audio-playing', playing);
  button.dataset.audioEnabled = String(playing);
  button.setAttribute('aria-label', playing ? t('audio.mute') : t('audio.enable'));
  suppressMediaSession();
}

function wireAudioToggle() {
  const audioButton = qs('button.button');
  if (!audioButton) return;

  suppressMediaSession();
  wireMusicLoop();

  // Restore current playing state across language changes or layout re-renders
  updateAudioState(audioButton, isAudioPlaying);

  if (audioButton.dataset.audioWired === 'true') return;
  audioButton.dataset.audioWired = 'true';

  audioButton.addEventListener('click', () => {
    // Click feedback bounce animation
    audioButton.classList.remove('ime-audio-clicking');
    void audioButton.offsetWidth;
    audioButton.classList.add('ime-audio-clicking');

    const frame = document.getElementById('music-player');
    if (!frame?.contentWindow) {
      showNotice(t('audio.unavailable'));
      return;
    }

    isAudioPlaying = !isAudioPlaying;
    updateAudioState(audioButton, isAudioPlaying);

    const send = (func, args = []) => {
      frame.contentWindow.postMessage(JSON.stringify({ event: 'command', func, args }), '*');
    };

    if (isAudioPlaying) {
      send('playVideo');
      send('unMute');
      window.setTimeout(() => send('unMute'), 400);
      showNotice(t('audio.enabled'));
    } else {
      send('pauseVideo');
      send('mute');
      showNotice(t('audio.muted'));
    }

    suppressMediaSession();
  });
}

export function wireActions() {
  wireGlobalListeners();
  wireLanguageSelector();
  wireCopyButtons();
  wireMobileMenu();
  wireAudioToggle();
}

export function refreshLanguageUi() {
  markActiveLanguage();
  const audioButton = qs('button.button');
  if (audioButton) {
    audioButton.setAttribute('aria-label', isAudioPlaying ? t('audio.mute') : t('audio.enable'));
  }
}

