export const qs = (selector, scope = document) => scope.querySelector(selector);
export const qsa = (selector, scope = document) => [...scope.querySelectorAll(selector)];

export function el(tag, className = '', text = '') {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text) node.textContent = text;
  return node;
}

export function setText(selector, value) {
  if (typeof value !== 'string') return;
  const node = qs(selector);
  if (node) node.textContent = value;
}

export function setLink(selector, value) {
  if (typeof value !== 'string') return;
  qsa(selector).forEach((node) => {
    if (node instanceof HTMLAnchorElement) node.href = safeUrl(value);
  });
}

export function safeUrl(value) {
  try {
    const url = new URL(value, window.location.origin);
    return ['https:', 'http:', 'fivem:', 'mailto:', 'tel:'].includes(url.protocol) ? url.href : '#';
  } catch {
    return '#';
  }
}

export function closestWithin(node, selector) {
  return node instanceof Element ? node.closest(selector) : null;
}

