import { el, qs } from './dom.js';
import { t } from './i18n.js';

let controller = null;
let currentSettings = {};

export function setFaqSettings(settings) {
  currentSettings = settings || {};
}

export function refreshFaqAnswer() {
  controller?.refresh();
}

export function wireFaqAccordion() {
  const faq = qs('.wrapper-149');
  if (!faq) return;

  const list = faq.querySelector('.scrollbar-thin');
  const panel = faq.querySelector('.scrollbar-thin-2');
  const buttons = [...(list?.querySelectorAll(':scope > button') || [])];
  if (!list || !panel || !buttons.length) return;

  const originalAnswer = panel.firstElementChild?.cloneNode(true) || null;
  let activeIndex = 0;

  const questions = buttons.map((button, index) => {
    const categorySelector = 'div[class^="wrapper-"] > div[class^="wrapper-"]';
    const category = button.querySelector(categorySelector)?.textContent.trim();
    const title = button.querySelector('h4')?.textContent.trim();
    const numberText = button.querySelector('div[class^="label-"]')?.textContent.trim() || String(index + 1);
    return {
      category: category || 'FAQ',
      title: title || `${t('faq.question')} ${index + 1}`,
      number: numberText
    };
  });

  function renderAnswer(index) {
    activeIndex = index;
    const answer = String(currentSettings.faq?.answers?.[index] || '').trim();
    panel.replaceChildren();
    buttons.forEach((item, buttonIndex) => {
      item.classList.toggle('ime-faq-active', buttonIndex === index);
      item.setAttribute('aria-expanded', String(buttonIndex === index));
    });

    // The rich original answer is preserved until an admin replaces FAQ #1 in the database.
    if (index === 0 && !answer && originalAnswer) {
      panel.append(originalAnswer.cloneNode(true));
      return;
    }

    const article = el('div', 'wrapper-172 ime-faq-live-answer');
    const category = el('span', 'label-74', questions[index]?.category || `FAQ ${index + 1}`);
    const title = el('h3', 'heading-58',
      questions[index]?.title || `${t('faq.question')} ${index + 1}`);
    const divider = el('div', 'wrapper-173');
    const body = el('div', 'wrapper-174');

    if (answer) {
      for (const paragraph of answer.split(/\n{2,}/)) {
        body.append(el('p', 'ime-faq-answer-paragraph', paragraph.trim()));
      }
    } else {
      body.append(el('p', 'ime-faq-empty', t('faq.empty')));
    }

    article.append(category, title, divider, body);
    panel.append(article);
  }

  buttons.forEach((button, index) => {
    button.type = 'button';
    button.addEventListener('click', () => renderAnswer(index));
  });

  // Wire search bar
  const searchInput = qs('#faq input') || qs('.placeholder-gray-500');
  const searchWrapper = searchInput?.closest('.wrapper-147');

  function updateSearchPlaceholder() {
    if (searchInput) {
      const translated = t('faq.searchPlaceholder');
      if (translated && !translated.startsWith('faq.')) {
        searchInput.placeholder = translated;
      }
    }
  }

  function filterFaq(query) {
    const q = (query || '').trim().toLowerCase();
    const matchingIndices = [];

    buttons.forEach((button, index) => {
      const question = questions[index];
      const answer = String(currentSettings.faq?.answers?.[index] || '').toLowerCase();
      const searchable = `${question.number} ${question.category} ${question.title} ${button.textContent} ${answer}`.toLowerCase();

      const matches = !q || searchable.includes(q);
      if (matches) {
        button.style.display = '';
        button.hidden = false;
        matchingIndices.push(index);
      } else {
        button.style.display = 'none';
        button.hidden = true;
      }
    });

    let emptyNotice = list.querySelector('.ime-faq-no-results');
    if (matchingIndices.length === 0) {
      const noResultsText = (!t('faq.noResults') || t('faq.noResults').startsWith('faq.'))
        ? 'Tidak ada pertanyaan yang cocok.'
        : t('faq.noResults');
      const noResultsTitle = (!t('faq.noResultsTitle') || t('faq.noResultsTitle').startsWith('faq.'))
        ? 'Hasil Tidak Ditemukan'
        : t('faq.noResultsTitle');
      const noResultsDesc = (!t('faq.noResultsDesc') || t('faq.noResultsDesc').startsWith('faq.'))
        ? 'Tidak ada kendala atau pertanyaan yang cocok dengan pencarian Anda. Coba kata kunci lain seperti Discord, Steam, atau FiniAC.'
        : t('faq.noResultsDesc');

      if (!emptyNotice) {
        emptyNotice = el('div', 'ime-faq-no-results', noResultsText);
        list.append(emptyNotice);
      } else {
        emptyNotice.textContent = noResultsText;
      }

      panel.replaceChildren();
      const emptyPanel = el('div', 'wrapper-172 ime-faq-live-answer');
      emptyPanel.append(
        el('h3', 'heading-58', noResultsTitle),
        el('div', 'wrapper-173'),
        el('p', 'ime-faq-empty', noResultsDesc)
      );
      panel.append(emptyPanel);
    } else {
      if (emptyNotice) emptyNotice.remove();
      if (!matchingIndices.includes(activeIndex)) {
        renderAnswer(matchingIndices[0]);
      }
    }
  }

  if (searchInput && searchInput.dataset.faqSearchWired !== 'true') {
    searchInput.dataset.faqSearchWired = 'true';

    // Clear button inside search wrapper
    let clearBtn = searchWrapper?.querySelector('.ime-faq-search-clear');
    if (!clearBtn && searchWrapper) {
      clearBtn = el('button', 'ime-faq-search-clear');
      clearBtn.type = 'button';
      clearBtn.setAttribute('aria-label', 'Clear search');
      clearBtn.textContent = '✕';
      clearBtn.style.display = 'none';
      clearBtn.addEventListener('click', () => {
        searchInput.value = '';
        clearBtn.style.display = 'none';
        filterFaq('');
        searchInput.focus();
      });
      searchWrapper.append(clearBtn);
    }

    searchInput.addEventListener('input', (e) => {
      const val = e.target.value;
      if (clearBtn) clearBtn.style.display = val ? 'flex' : 'none';
      filterFaq(val);
    });

    searchInput.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        searchInput.value = '';
        if (clearBtn) clearBtn.style.display = 'none';
        filterFaq('');
      }
    });
  }

  updateSearchPlaceholder();

  controller = {
    refresh: () => {
      updateSearchPlaceholder();
      renderAnswer(activeIndex);
      if (searchInput && searchInput.value) {
        filterFaq(searchInput.value);
      }
    }
  };

  renderAnswer(0);
}

