import { API, FALLBACK_LOCALE, STORAGE_KEYS } from './config.js';
import { qsa } from './dom.js';

const cache = new Map();
let catalog = { locales: [], defaultLocale: FALLBACK_LOCALE };
let activeCode = FALLBACK_LOCALE;
let active = { ui: {}, content: {} };
let siteDefault = FALLBACK_LOCALE;

const listeners = new Set();

function normalize(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

async function fetchLocale(code) {
  if (cache.has(code)) return cache.get(code);
  const entry = catalog.locales.find((item) => item.code === code);
  if (!entry) return null;
  try {
    const response = await fetch(`/locales/${entry.file}`, { cache: 'force-cache' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    const normalized = {
      ui: data.ui || {},
      content: data.content || {},
      meta: {
        code,
        short: entry.short || code.toUpperCase(),
        label: entry.label,
        flag: entry.flag,
        direction: data.direction || 'ltr'
      }
    };
    cache.set(code, normalized);
    return normalized;
  } catch (error) {
    console.warn(`[i18n] Locale ${code} could not be loaded:`, error.message);
    return null;
  }
}

export async function initI18n() {
  try {
    const response = await fetch(API.locales, { cache: 'no-store' });
    if (response.ok) {
      const data = await response.json();
      catalog = {
        locales: Array.isArray(data.locales) ? data.locales : [],
        defaultLocale: data.defaultLocale || FALLBACK_LOCALE
      };
      siteDefault = catalog.defaultLocale;
    }
  } catch {
    // A failed catalog request keeps the built-in English defaults.
  }

  const stored = window.localStorage.getItem(STORAGE_KEYS.locale);
  const candidate = stored || siteDefault || FALLBACK_LOCALE;
  await setLocale(candidate, { silent: true, persist: false });
  return activeCode;
}

export function getLocale() {
  return activeCode;
}

export function getLocaleMeta() {
  return catalog.locales.find((item) => item.code === activeCode) || null;
}

export function listLocales() {
  return catalog.locales;
}

export function t(key, fallback = '') {
  return active.ui[key] ?? key ?? fallback;
}

export function onLocaleChange(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function translateText(value) {
  const text = normalize(value);
  if (!text) return value;
  const translated = active.content[text];
  if (!translated) return value;
  return value.replace(value.trim(), translated);
}

export function translateTree(root) {
  if (!root || !Object.keys(active.content).length) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const updates = [];
  let node = walker.nextNode();
  while (node) {
    const translated = active.content[normalize(node.nodeValue)];
    if (translated) updates.push([node, translated]);
    node = walker.nextNode();
  }
  for (const [textNode, value] of updates) textNode.nodeValue = value;
}

export function translateAttributes(root) {
  if (!root || !Object.keys(active.content).length) return;
  for (const node of qsa('[aria-label], [title], [alt], [placeholder]', root)) {
    for (const attribute of ['aria-label', 'title', 'alt', 'placeholder']) {
      const current = node.getAttribute(attribute);
      if (!current) continue;
      const translated = active.content[normalize(current)];
      if (translated) node.setAttribute(attribute, translated);
    }
  }
}

export async function setLocale(code, options = {}) {
  const { silent = false, persist = true } = options;
  const requested = catalog.locales.some((item) => item.code === code) ? code : FALLBACK_LOCALE;
  let bundle = await fetchLocale(requested);
  if (!bundle && requested !== FALLBACK_LOCALE) bundle = await fetchLocale(FALLBACK_LOCALE);
  if (!bundle) return activeCode;

  activeCode = bundle.meta.code;
  active = bundle;
  document.documentElement.lang = activeCode;
  document.documentElement.dir = bundle.meta.direction || 'ltr';
  if (persist) window.localStorage.setItem(STORAGE_KEYS.locale, activeCode);
  if (!silent) listeners.forEach((listener) => listener(activeCode, bundle));
  return activeCode;
}

export function formatNotice(key, replacements = {}) {
  let message = t(key);
  for (const [token, value] of Object.entries(replacements)) {
    message = message.replaceAll(`{${token}}`, String(value));
  }
  return message;
}

