import { safeUrl } from './dom.js';
import { translateAttributes, translateTree } from './i18n.js';

const ALLOWED_TAGS = new Set([
  'a', 'abbr', 'article', 'b', 'blockquote', 'br', 'button', 'div',
  'em', 'footer', 'h1', 'h2', 'h3', 'h4', 'h5', 'header', 'i',
  'iframe', 'img', 'input', 'li', 'main', 'nav', 'ol', 'p',
  'section', 'small', 'span', 'strong', 'sub', 'sup', 'ul'
]);

const ALLOWED_ATTRIBUTES = new Set([
  'id', 'class', 'style', 'href', 'src', 'alt', 'title', 'width', 'height', 'target', 'rel',
  'role', 'tabindex', 'aria-label', 'aria-expanded', 'aria-hidden', 'allow', 'allowfullscreen',
  'frameborder', 'referrerpolicy', 'loading', 'decoding', 'draggable', 'name', 'type',
  'placeholder', 'value'
]);

function build(spec) {
  if (!spec || typeof spec !== 'object') return document.createTextNode('');
  if (spec.type === 'text') return document.createTextNode(String(spec.value ?? ''));
  if (spec.type !== 'element' || !ALLOWED_TAGS.has(spec.tag)) return document.createDocumentFragment();

  const node = document.createElement(spec.tag);
  for (const [key, raw] of Object.entries(spec.attrs || {})) {
    if (!ALLOWED_ATTRIBUTES.has(key) || /^on/i.test(key) || key === 'srcdoc') continue;
    let value = String(raw ?? '');
    if (key === 'href' || key === 'src') {
      value = safeUrl(value);
      if (value === '#') continue;
    }
    node.setAttribute(key, value);
  }
  for (const child of spec.children || []) node.append(build(child));
  return node;
}

export function renderLayout(layout, onRendered) {
  const app = document.getElementById('app');
  if (!app || !layout) return false;
  const fragment = document.createDocumentFragment();
  fragment.append(build(layout));
  app.replaceChildren(fragment);

  // Assets are part of the design; keep them from being dragged out of the browser.
  app.querySelectorAll('img').forEach((image) => {
    image.draggable = false;
  });

  translateTree(app);
  translateAttributes(app);
  if (typeof onRendered === 'function') onRendered();
  return true;
}

