import { API } from './config.js';
import { initI18n, onLocaleChange } from './i18n.js';
import { renderLayout } from './layout.js';
import { applySettings, setSettingsHooks } from './settings.js';
import { renderStaff } from './staff.js';
import { refreshRules, setRulesSettings, wireRuleCategories } from './rules.js';
import { refreshFaqAnswer, setFaqSettings, wireFaqAccordion } from './faq.js';
import { refreshLanguageUi, setLocaleHandler, wireActions } from './actions.js';
import {
  createPreloader,
  heroVideoReady,
  imageReady,
  imagesReady,
  stylesReady
} from '../shared/preloader.js';

const state = {
  settings: {},
  staff: [],
  layout: null,
  layoutRevision: '',
  revision: '',
  settingsKey: '',
  staffKey: '',
  fallbackTimer: 0
};

function renderContent() {
  renderLayout(state.layout, () => {
    wireActions();
    wireRuleCategories();
    wireFaqAccordion();
  });
  applySettings(state.settings);
  renderStaff(state.staff, state.settings);
  refreshLanguageUi();
}

function applyPayload(data) {
  state.settings = data.settings || {};
  state.staff = data.staff || [];
  state.layout = data.layout || state.layout;
  state.layoutRevision = String(data.layoutRevision || '');
  state.revision = data.revision || '';
  state.settingsKey = JSON.stringify(state.settings);
  state.staffKey = JSON.stringify(state.staff);
  setRulesSettings(state.settings);
  setFaqSettings(state.settings);
}

async function fetchSite() {
  try {
    const response = await fetch(API.site, {
      cache: 'no-store',
      headers: { Accept: 'application/json' }
    });
    if (!response.ok) return null;
    return await response.json();
  } catch (error) {
    console.warn('[site] Content could not be loaded:', error.message);
    return null;
  }
}

// Only the parts that changed are re-rendered, so a live Discord update never
// flashes the whole layout.
async function refresh() {
  const data = await fetchSite();
  if (!data) return;

  const settingsChanged = JSON.stringify(data.settings || {}) !== state.settingsKey;
  const staffChanged = JSON.stringify(data.staff || []) !== state.staffKey;
  const layoutChanged = state.layoutRevision !== String(data.layoutRevision || '');
  const firstLoad = !state.revision;

  if (!firstLoad && !settingsChanged && !staffChanged && !layoutChanged) return;

  applyPayload(data);

  if (firstLoad || layoutChanged) {
    renderContent();
    return;
  }
  if (settingsChanged) applySettings(state.settings);
  if (settingsChanged || staffChanged) renderStaff(state.staff, state.settings);
}

function startEventStream() {
  const events = new EventSource(API.events);
  events.onmessage = () => refresh();
  events.onerror = () => {
    // EventSource reconnects on its own; the timer only covers a dropped stream.
  };

  const seconds = Math.max(15, Math.min(300, Number(state.settings?.appearance?.refreshSeconds) || 45));
  window.clearInterval(state.fallbackTimer);
  state.fallbackTimer = window.setInterval(() => {
    if (events.readyState !== EventSource.OPEN) refresh();
  }, seconds * 1000);
}

function showLoadFailure() {
  const app = document.getElementById('app');
  if (!app) return;
  const box = document.createElement('div');
  box.className = 'ime-site-notice is-visible';
  box.textContent = 'The website could not load its content. Please refresh the page.';
  document.body.append(box);
}

async function boot() {
  const lang = (localStorage.getItem('waktu-senja.locale') || navigator.language || 'id').toLowerCase();
  const isId = lang.startsWith('id');
  const isMs = lang.startsWith('ms');

  const preloaderLabels = isId ? {
    styles: 'Memuat gaya desain...',
    fonts: 'Menyiapkan tipografi...',
    logo: 'Memuat identitas kota...',
    locale: 'Menyiapkan bahasa...',
    data: 'Mengambil data kota...',
    render: 'Menyusun halaman...',
    images: 'Memuat aset visual',
    video: 'Menyiapkan video panggung...',
    ready: 'Selamat datang di Waktu Senja'
  } : isMs ? {
    styles: 'Memuatkan gaya reka bentuk...',
    fonts: 'Menyediakan tipografi...',
    logo: 'Memuatkan identiti bandar...',
    locale: 'Menyediakan bahasa...',
    data: 'Mengambil data bandar...',
    render: 'Membina susun atur...',
    images: 'Memuatkan karya visual',
    video: 'Menyediakan tayangan bandar...',
    ready: 'Selamat datang ke Waktu Senja'
  } : {
    styles: 'Loading styles',
    fonts: 'Preparing typography',
    logo: 'Loading brand identity',
    locale: 'Loading language',
    data: 'Fetching city data',
    render: 'Building layout',
    images: 'Loading artwork',
    video: 'Buffering showreel',
    ready: 'Welcome to Waktu Senja'
  };

  const preloader = createPreloader({
    tasks: ['styles', 'fonts', 'logo', 'locale', 'data', 'render', 'images', 'video'],
    weights: {
      styles: 12,
      fonts: 10,
      logo: 6,
      locale: 10,
      data: 20,
      render: 10,
      images: 22,
      video: 10
    },
    labels: preloaderLabels
  });

  preloader.track('styles', stylesReady());
  preloader.track('fonts', document.fonts?.ready || Promise.resolve());
  preloader.track('logo', imageReady(document.querySelector('.preloader-logo')));

  const localeReady = initI18n();
  preloader.track('locale', localeReady);
  await localeReady;

  setLocaleHandler(() => renderContent());
  setSettingsHooks({ refreshRules, refreshFaq: refreshFaqAnswer });
  onLocaleChange(() => refreshLanguageUi());

  const dataPromise = fetchSite();
  preloader.track('data', dataPromise);
  const data = await dataPromise;

  const app = document.getElementById('app');
  let videoPromise = Promise.resolve();

  if (data) {
    applyPayload(data);
    renderContent();

    const heroFrame = document.getElementById('player');
    if (heroFrame) {
      videoPromise = heroVideoReady(heroFrame);
      preloader.track('video', videoPromise);
    } else {
      preloader.mark('video');
    }
  } else {
    showLoadFailure();
    preloader.mark('video');
  }

  preloader.mark('render');

  // Track each real image asset individually with real network download progress
  const allImages = [...new Set(document.querySelectorAll('#app img, #root img, img'))]
    .filter((img) => img !== document.querySelector('.preloader-logo'));

  if (allImages.length) {
    let loadedCount = 0;
    const total = allImages.length;
    const imgLabel = preloaderLabels.images;
    preloader.status(`${imgLabel} (0/${total})`);

    await Promise.all(allImages.map((img) => {
      return new Promise((resolve) => {
        let finished = false;
        const onImageFinished = () => {
          if (finished) return;
          finished = true;
          loadedCount++;
          const currentCount = Math.min(loadedCount, total);
          preloader.stepFraction('images', currentCount, total);
          preloader.status(`${imgLabel} (${currentCount}/${total})`);
          resolve();
        };

        if (img.complete && img.naturalWidth > 0) {
          onImageFinished();
        } else {
          img.addEventListener('load', onImageFinished, { once: true });
          img.addEventListener('error', onImageFinished, { once: true });
          window.setTimeout(onImageFinished, 6500);
        }
      });
    }));
    preloader.mark('images');
  } else {
    preloader.mark('images');
  }

  if (app) app.removeAttribute('aria-busy');
  await videoPromise;
  await preloader.complete();
  startEventStream();
}

document.addEventListener('DOMContentLoaded', () => {
  boot().catch((error) => console.error('[site] Bootstrap failed:', error));
});

