let activeCategory = 0;
let currentSettings = {};

export function setRulesSettings(settings) {
  currentSettings = settings || {};
}

export function refreshRules() {
  if (activeCategory > 0) renderRuleCategory(activeCategory);
}

export function renderRuleCategory(index) {
  const container = qs('.custom-scrollbar');
  const defaultContent = container?.querySelector(':scope > .wrapper-92');
  if (!container || !defaultContent) return;

  let dynamic = container.querySelector(':scope > .ime-rule-category-content');
  if (index === 0) {
    defaultContent.hidden = false;
    dynamic?.remove();
    return;
  }

  defaultContent.hidden = true;
  if (!dynamic) {
    dynamic = el('div', 'wrapper-92 ime-rule-category-content');
    container.append(dynamic);
  }
  dynamic.replaceChildren();

  const category = index === 1 ? currentSettings.rules?.robbery
    : index === 2 ? currentSettings.rules?.criminal
      : currentSettings.rules?.dictionary;
  const fallbackTitle = index === 1 ? 'Robbery Rules'
    : index === 2 ? 'Criminal Rules' : 'RP Dictionary';

  const heading = el('h2', 'heading-9', category?.title || fallbackTitle);
  dynamic.append(heading);

  const content = String(category?.content || '').trim();
  if (!content) {
    dynamic.append(el('p', 'ime-rule-empty', t('rules.empty')));
    return;
  }
  for (const paragraph of content.split(/\n{2,}/)) {
    dynamic.append(el('p', 'ime-rule-paragraph', paragraph.trim()));
  }
}

export function wireRuleCategories() {
  const filters = qsa('.wrapper-91 button');
  if (!filters.length) return;

  filters.forEach((button, index) => {
    button.addEventListener('click', () => {
      filters.forEach((item) => item.classList.remove('ime-filter-active'));
      button.classList.add('ime-filter-active');
      filters.forEach((item, itemIndex) =>
        item.setAttribute('aria-pressed', String(itemIndex === index)));
      activeCategory = index;
      renderRuleCategory(index);
    });
  });

  filters[0]?.classList.add('ime-filter-active');
  renderRuleCategory(0);
}

