function staffColumns(settings) {
  return Math.max(1, Math.min(8, Number(settings.staff?.maxColumns) || 4));
}

function applyAccent(color) {
  if (!/^#[0-9a-f]{6}$/i.test(color || '')) return;
  const channels = [1, 3, 5].map((offset) => Number.parseInt(color.slice(offset, offset + 2), 16));
  document.documentElement.style.setProperty('--ime-accent', color);
  document.documentElement.style.setProperty('--ime-accent-rgb', channels.join(', '));
}

function applyBrandName(brandName) {
  if (typeof brandName !== 'string' || !brandName.trim()) return;
  const brandLabel = qs('.wrapper-6 .label');
  if (!brandLabel) return;
  const brandAccent = brandLabel.querySelector('.label-2');
  if (brandAccent) {
    const words = brandName.trim().split(/\s+/);
    const accent = words.pop() || brandName.trim();
    const prefixNode = [...brandLabel.childNodes].find((node) =>
      node.nodeType === Node.TEXT_NODE && node.textContent.trim());
    if (prefixNode) prefixNode.textContent = words.length ? `${words.join(' ')} ` : '';
    brandAccent.textContent = accent;
  } else {
    brandLabel.textContent = brandName.trim();
  }
  document.title = brandName.trim();
}

export function applySectionOrder(settings) {
  const root = qs('.wrapper-197');
  if (!root) return;
  const grid = root.querySelector(':scope > .wrapper-208');
  const founders = root.querySelector(':scope > .wrapper-200');
  const admin = root.querySelector(':scope > .wrapper-220');
  const helper = root.querySelector(':scope > .wrapper-247');
  const management = grid?.querySelector(':scope > .wrapper-209') || root.querySelector(':scope > .wrapper-209');
  const developers = grid?.querySelector(':scope > .wrapper-212') || root.querySelector(':scope > .wrapper-212');
  if (!grid || !founders || !admin || !helper || !management || !developers) return;

  // Extra bottom sections (Staff Discord + Asset & Graphics, Brand Ambassador).
  // These are not part of the configurable section order and always render last,
  // below Helper Team.
  const bottomSections = [...root.children].filter((node) =>
    node.classList.contains('wrapper-279') || node.classList.contains('wrapper-308'));

  const supported = ['founders', 'management', 'developers', 'admin', 'helper'];
  const requested = Array.isArray(settings.staff?.sectionOrder)
    ? settings.staff.sectionOrder.filter((item, index, list) =>
        supported.includes(item) && list.indexOf(item) === index)
    : supported;
  const order = [...requested, ...supported.filter((item) => !requested.includes(item))];

  if (order.join(',') === supported.join(',')) {
    // Management and developers stay side by side inside the two-column grid.
    grid.hidden = false;
    grid.append(management, developers);
    root.append(founders, grid, admin, helper);
  } else {
    // A custom order pulls every section out of the grid so it can be stacked
    // in the requested sequence.
    grid.hidden = true;
    const sections = { founders, management, developers, admin, helper };
    for (const section of order) root.append(sections[section]);
  }
  root.append(...bottomSections);

  const intro = root.querySelector(':scope > .wrapper-198');
  if (intro) root.insertBefore(intro, root.firstChild);
}

let youTubeApiPromise = null;

function loadYouTubeApi() {
  if (window.YT?.Player) return Promise.resolve(window.YT);
  if (youTubeApiPromise) return youTubeApiPromise;

  youTubeApiPromise = new Promise((resolve) => {
    const script = document.createElement('script');
    script.src = 'https://www.youtube.com/iframe_api';
    script.async = true;
    script.onerror = () => resolve(null);
    window.onYouTubeIframeAPIReady = () => resolve(window.YT || null);
    document.head.append(script);

    // The API can load without ever calling its callback, for example when a
    // browser extension interferes. The plain embed is used instead.
    window.setTimeout(() => resolve(window.YT || null), 6000);
  });

  return youTubeApiPromise;
}

function announceHeroVideo(state) {
  document.documentElement.dataset.heroVideoState = state;
  document.dispatchEvent(new CustomEvent('ime:hero-video', { detail: { state } }));
}

async function applyHeroVideo(settings) {
  const video = qs('iframe#player') || qs('iframe.frame');
  const id = settings.media?.heroYoutubeId;
  if (!video || !/^[A-Za-z0-9_-]{11}$/.test(id || '')) return;
  if (video.dataset.heroVideo === id) return;

  const params = {
    autoplay: 1, controls: 0, loop: 1, mute: 1,
    rel: 0, playsinline: 1, enablejsapi: 1, origin: window.location.origin
  };
  const title = settings.media?.youtubeTitle || '';

  // The embed url is set before the player API takes over, so the video starts
  // loading right away and the loader can wait for a real load event.
  const videoUrl = new URL(`https://www.youtube.com/embed/${id}`);
  for (const [key, value] of Object.entries(params)) videoUrl.searchParams.set(key, String(value));
  if (video.src !== videoUrl.toString()) video.src = videoUrl.toString();
  if (title) video.title = title;
  video.dataset.heroVideo = id;

  const api = await loadYouTubeApi();
  if (!api?.Player) {
    announceHeroVideo('ready');
    return;
  }

  const player = new api.Player(video, {
    videoId: id,
    playerVars: params,
    events: {
      onReady: (event) => {
        try {
          event.target.mute?.();
          event.target.playVideo?.();
        } catch {}
        announceHeroVideo('ready');
      },
      onStateChange: (event) => {
        if (event.data === 0) {
          try {
            event.target.seekTo(0);
            event.target.playVideo();
          } catch {}
        }
      },
      onError: (event) => {
        // 100 = not found, 101 and 150 = the owner does not allow embedding.
        if (![100, 101, 150].includes(event.data)) return;
        video.classList.add('is-unavailable');
        video.hidden = true;
        announceHeroVideo('failed');
      }
    }
  });
  if (title) player.setTitle?.(title);
}

// The background video and the website music are two independent YouTube players.
function applyMusicPlayer(settings) {
  const id = settings.media?.musicYoutubeId;
  if (!/^[A-Za-z0-9_-]{11}$/.test(id || '')) return;

  let frame = document.getElementById('music-player');
  if (!frame) {
    frame = document.createElement('iframe');
    frame.id = 'music-player';
    frame.className = 'ime-music-player';
    frame.setAttribute('aria-hidden', 'true');
    frame.setAttribute('tabindex', '-1');
    frame.setAttribute('allow', 'autoplay; encrypted-media');
    frame.title = settings.media?.musicYoutubeTitle || 'Website music';
    document.body.append(frame);
  }

  const url = new URL(`https://www.youtube.com/embed/${id}`);
  const params = {
    autoplay: '0', controls: '0', loop: '1',
    playsinline: '1', enablejsapi: '1', rel: '0',
    origin: window.location.origin
  };
  for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value);
  if (frame.src !== url.toString()) frame.src = url.toString();
  if (settings.media?.musicYoutubeTitle) frame.title = settings.media.musicYoutubeTitle;
}

function applyButtonVisibility(settings) {
  qsa('.link-8, .link-18').forEach((button) => {
    button.hidden = settings.buttons?.showPlayButton === false;
  });
  const discordButton = qs('.link-19');
  if (discordButton) discordButton.hidden = settings.buttons?.showDiscordButton === false;
  const cacheButton = qs('.link-20');
  if (cacheButton) cacheButton.hidden = settings.buttons?.showCacheButton === false;
}

function applyLinkOverrides(overrides) {
  if (!overrides || typeof overrides !== 'object') return;
  for (const [selector, value] of Object.entries(overrides)) {
    if (typeof value !== 'string' || selector.length > 180) continue;
    try {
      qsa(selector).forEach((node) => {
        if (node instanceof HTMLAnchorElement) {
          node.href = safeUrl(value);
        } else if (node instanceof HTMLButtonElement) {
          node.dataset.destination = value.startsWith('#')
            || (value.startsWith('/') && !value.startsWith('//'))
            ? value
            : safeUrl(value);
        }
      });
    } catch {
      // An invalid admin selector is skipped without breaking the page.
    }
  }
}

function applyTextOverrides(overrides) {
  if (!overrides || typeof overrides !== 'object') return;
  for (const [selector, value] of Object.entries(overrides)) {
    if (typeof value !== 'string' || selector.length > 180) continue;
    try {
      qsa(selector).forEach((node) => { node.textContent = value; });
    } catch {
      // An invalid admin selector is skipped without breaking the page.
    }
  }
}

export function applySettings(settings) {
  applySectionOrder(settings);
  applyAccent(settings.appearance?.accentColor);
  applyBrandName(settings.brand?.name);

  const columns = staffColumns(settings);
  document.documentElement.style.setProperty('--ime-staff-columns', String(columns));
  document.documentElement.style.setProperty('--ime-staff-columns-tablet', String(Math.min(columns, 2)));

  setText('.wrapper-6 .label-3', settings.brand?.tagline);
  setText('.label-98', settings.copy?.footerText);

  const staffHeading = qs('.heading-73');
  if (settings.copy?.staffHeading && staffHeading) {
    const headingText = [...staffHeading.childNodes].find((item) =>
      item.nodeType === Node.TEXT_NODE && item.textContent.trim());
    if (headingText) headingText.textContent = ` ${settings.copy.staffHeading} `;
  }

  setLink('.link-19, .link-22, .link-27', settings.links?.discord);
  setLink('.link-20', settings.links?.cache);
  setLink('.link-8, .link-18', settings.links?.play);
  setLink('.link-31', settings.links?.youtubeChannel);

  applyHeroVideo(settings).catch((error) => {
    console.warn('[site] Background video could not be prepared:', error.message);
    announceHeroVideo('failed');
  });
  applyMusicPlayer(settings);
  applyButtonVisibility(settings);
  applyLinkOverrides(settings.links?.overrides);
  applyTextOverrides(settings.copy?.textOverrides);

  hooks.refreshRules();
  hooks.refreshFaq();

  const app = document.getElementById('app');
  translateTree(app);
  translateAttributes(app);
}

