import { el, qs, qsa } from './dom.js';
import { t } from './i18n.js';

const staffCardProfiles = {
  founders: { card: 'wrapper-202', image: 'image-17', name: 'heading-64', title: 'text-14' },
  management: { card: 'wrapper-210', image: 'image-19', name: 'heading-67', title: 'text-16' },
  developers: { card: 'wrapper-214', image: 'image-20', name: 'heading-69', title: 'label-93' },
  'head-admin': { card: 'wrapper-227', image: 'image-24', name: 'wrapper-228' },
  admin: { card: 'wrapper-227', image: 'image-24', name: 'wrapper-228' },
  staff: { card: 'wrapper-227', image: 'image-24', name: 'wrapper-228' },
  helper: { card: 'wrapper-249', image: 'image-34', name: 'wrapper-250' },
  'staff-discord': { card: 'wrapper-282', image: 'image-49', name: 'wrapper-283' },
  'assets-graphics': { card: 'wrapper-288', image: 'image-51', name: 'wrapper-289' },
  'brand-ambassador': { card: 'wrapper-310', image: 'image-61', name: 'wrapper-311' }
};

const CARD_SELECTOR = '.ime-discord-staff-card, .ime-live-staff-card, .ime-staff-empty';

function avatarNode(className, person) {
  const image = el('img', className);
  image.src = person.avatar || ASSETS.logo;
  image.alt = `${person.name} — ${person.title}`;
  image.loading = 'lazy';
  image.referrerPolicy = 'no-referrer';
  return image;
}

function createStaffCard(person, index, section = 'staff') {
  const profile = staffCardProfiles[section];
  if (!profile) {
    const fallback = el('article', 'ime-live-staff-card');
    fallback.append(
      avatarNode('', person),
      el('strong', '', person.name),
      el('span', '', person.title)
    );
    return fallback;
  }

  const card = el('div', `${profile.card} ime-discord-staff-card`);
  card.style.setProperty('--staff-index', String(index));
  const image = avatarNode(profile.image, person);
  const name = el(profile.name.startsWith('heading-') ? 'h4' : 'div', profile.name, person.name);

  if (section === 'founders') {
    const frame = el('div', 'wrapper-203');
    frame.append(el('div', 'wrapper-204'), image);
    card.append(frame, name, el('p', profile.title, person.title));
    return card;
  }

  if (section === 'management' || section === 'developers') {
    const details = el('div', section === 'management' ? 'wrapper-211' : 'wrapper-215');
    const title = el(section === 'management' ? 'p' : 'span', profile.title, person.title);
    details.append(name, title);
    card.append(image, details);
    return card;
  }

  card.append(image, name);
  return card;
}

function emptyStaffMessage() {
  return el('p', 'ime-staff-empty', t('staff.empty'));
}

function renderHeadAdmins(headAdmins) {
  const container = qs('.wrapper-223');
  const separator = qs('.wrapper-224');
  if (!container) return;

  if (!headAdmins || !headAdmins.length) {
    container.hidden = true;
    if (separator) separator.hidden = true;
    return;
  }

  container.hidden = false;
  if (separator) separator.hidden = false;
  container.innerHTML = '';

  headAdmins.forEach((person) => {
    const item = el('div', 'ime-head-admin-item');
    const image = el('img', 'image-23');
    image.src = person.avatar || ASSETS.logo;
    image.alt = `${person.name} — ${person.title || 'Head Admin'}`;
    image.draggable = false;
    image.loading = 'lazy';
    image.referrerPolicy = 'no-referrer';

    const label = el('span', 'label-96');
    const icon = el('i', 'fas-31');
    const roleSpan = el('span', 'ime-featured-role', person.title || 'Head Admin');
    label.append(icon, roleSpan);

    const name = el('h3', 'heading-72', person.name);

    item.append(image, label, name);
    container.append(item);
  });
}

function findHeading(pattern) {
  return qsa('h3').find((node) => pattern.test(node.textContent));
}

function renderMappedSection(staff, section, container, settings) {
  if (!container) return;
  container.querySelectorAll(CARD_SELECTOR).forEach((node) => node.remove());

  const live = settings.appearance?.liveStaffEnabled !== false;
  if (section === 'management' || section === 'developers') {
    container.replaceChildren();
    container.classList.add('ime-live-staff-list');
  } else {
    container.querySelectorAll(':scope > .ime-discord-staff-card').forEach((node) => node.remove());
  }
  if (!live) return;

  const people = staff.filter((person) => person.section === section);
  const columns = Math.max(1, Math.min(8, Number(settings.staff?.maxColumns) || 4));
  container.style.setProperty('--ime-staff-columns', String(columns));
  container.style.setProperty('--ime-staff-columns-tablet', String(Math.min(columns, 2)));

  if (people.length) {
    people.forEach((person, index) => container.append(createStaffCard(person, index, section)));
  } else {
    container.append(emptyStaffMessage());
  }
}

export function renderStaff(staff, settings) {
  const staffHeading = qs('.heading-73');
  const helperHeading = qs('.heading-74');
  if (!staffHeading || !helperHeading) return;

  const adminContainer = staffHeading.parentElement.querySelector('.wrapper-226');
  const helperContainer = helperHeading.parentElement.querySelector('.wrapper-248');
  if (!adminContainer || !helperContainer) return;

  const live = settings.appearance?.liveStaffEnabled !== false;
  qsa(CARD_SELECTOR).forEach((node) => node.remove());

  const headAdmins = live ? staff.filter((person) => person.section === 'head-admin') : [];
  const admins = live ? staff.filter((person) => person.section === 'admin') : [];
  const otherStaff = live ? staff.filter((person) => person.section === 'staff') : [];
  const helpers = live ? staff.filter((person) => person.section === 'helper') : [];

  renderHeadAdmins(headAdmins);

  const listedStaff = [...admins, ...otherStaff];
  listedStaff.forEach((person, index) => adminContainer.append(createStaffCard(person, index, 'admin')));
  helpers.forEach((person, index) => helperContainer.append(createStaffCard(person, index, 'helper')));

  if (live && !listedStaff.length) {
    const note = emptyStaffMessage();
    note.textContent = headAdmins.length ? t('staff.leadAdminAbove') : t('staff.empty');
    adminContainer.append(note);
  }
  if (live && !helpers.length) helperContainer.append(emptyStaffMessage());

  const founderWrap = qs('.wrapper-201');
  const managementWrap = qs('.wrapper-210');
  const developerWrap = qs('.wrapper-213');

  renderMappedSection(staff, 'founders', founderWrap, settings);
  renderMappedSection(staff, 'management', managementWrap, settings);
  renderMappedSection(staff, 'developers', developerWrap, settings);

  renderMappedSection(staff, 'staff-discord', qs('.wrapper-281'), settings);
  renderMappedSection(staff, 'assets-graphics', qs('.wrapper-287'), settings);
  renderMappedSection(staff, 'brand-ambassador', qs('.wrapper-309'), settings);
}

