import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import fs from 'node:fs/promises';
import path from 'node:path';
import { rootDir } from '../src/config.js';

const run = promisify(execFile);
const targets = ['server.js', 'src', 'public/js', 'scripts'];
const files = [];

async function collect(entry) {
  const full = path.join(rootDir, entry);
  const stat = await fs.stat(full).catch(() => null);
  if (!stat) return;
  if (stat.isDirectory()) {
    for (const child of await fs.readdir(full)) {
      if (child === 'node_modules') continue;
      await collect(path.join(entry, child));
    }
    return;
  }
  if (/\.(mjs|js)$/.test(entry)) files.push(entry);
}

for (const target of targets) await collect(target);

let failed = 0;
for (const file of files.sort()) {
  try {
    await run(process.execPath, ['--check', path.join(rootDir, file)]);
  } catch (error) {
    failed++;
    console.error(`\n✗ ${file}\n${error.stderr || error.message}`);
  }
}

const label = failed === 0 ? 'All files passed' : `${failed} file(s) failed`;
console.log(`${label} — ${files.length} JavaScript file(s) checked.`);
process.exitCode = failed === 0 ? 0 : 1;

